/* ---------- sheets ---------- */
function openSheet(html,bind){let el=$('#sheet');if(!el){el=document.createElement('div');el.id='sheet';el.className='sheet';document.body.appendChild(el);}
  el.innerHTML=`<div class="pnl">${html}<button class="btn ghost" data-close>Close</button></div>`;el.onclick=e=>{if(e.target===el)closeSheet();};
  el.querySelector('[data-close]').onclick=closeSheet;S.sheet=true;if(bind)bind(el);}
function closeSheet(){const el=$('#sheet');if(el)el.remove();S.sheet=null;}
function confirmSheet(msg,yes,onYes){openSheet(`<h3>${msg}</h3><button class="btn" id="cfy">${yes}</button>`,el=>el.querySelector('#cfy').onclick=()=>{closeSheet();onYes();});}

/* ---------- onboarding (first run) ---------- */
const OB={step:0,name:'',phone:'',addr:'',owner:'',pin:'',pin1:''};
function renderOnboard(){
  const st=OB;let body='';
  if(st.step===0)body=`<div class="ob-hero"><span class="wsmark big">＋</span><h2>New workshop</h2><p>Set up in 2 minutes. You can change everything later.</p></div>
    <input class="field" id="obn" placeholder="Workshop name" value="${esc(st.name)}" autocomplete="off">
    <input class="field" id="obp" placeholder="Workshop phone" inputmode="tel" value="${esc(st.phone)}">
    <input class="field" id="oba" placeholder="Area / city (optional)" value="${esc(st.addr)}">
    <button class="btn" id="obnext">Next</button>`;
  else if(st.step===1)body=`<h2>Owner name</h2><p>This is you. You add workers later.</p><input class="field" id="obo" placeholder="Your name" value="${esc(st.owner)}" autocomplete="off"><button class="btn" id="obnext">Next</button>`;
  else body=`<h2>${st.step===2?'Choose your PIN (4 numbers)':'Enter the PIN again'}</h2>${dots(st.pin.length)}${pad()}<div class="err" id="err"></div>`;
  $('#root').innerHTML=`<div class="login"><div class="in">${body}</div></div>`;
  if(st.step===0){$('#obnext').onclick=()=>{st.name=$('#obn').value.trim();st.phone=$('#obp').value.trim();st.addr=$('#oba').value.trim();if(!st.name){toast('Type the workshop name');return;}st.step=1;renderOnboard();};return;}
  if(st.step===1){$('#obnext').onclick=()=>{st.owner=$('#obo').value.trim()||'Owner';st.step=2;renderOnboard();};return;}
  bindPad(async k=>{
    if(k==='⌫')st.pin=st.pin.slice(0,-1);else if(st.pin.length<4)st.pin+=k;
    if(st.pin.length===4){
      if(st.step===2){st.pin1=st.pin;st.pin='';st.step=3;renderOnboard();return;}
      if(st.pin!==st.pin1){st.pin='';st.step=2;renderOnboard();$('#err').textContent='PINs did not match. Try again.';return;}
      DB.ws={name:st.name,phone:st.phone,addr:st.addr,logo:'',currency:'OMR',invStart:1001,nextInv:1001,nextJob:1,credDays:30,warranty:'',pay:['Cash','Card','Transfer','Credit'],vat:false,vatDecided:false,remMonths:6,remKm:7000,remMsg:'',svcReviewed:false,created:now()};
      DB.services=DEFAULT_SERVICES.map(([cat,name,a,b,tag])=>({id:uid('s'),cat,name,p:[a,b],tag:tag||''}));
      const u={id:uid('u'),name:st.owner,role:'owner',pin:await hashPin(st.pin),color:COLORS[0]};DB.users=[u];save();S.user=u;DB.seenNews=window.WS_VN||'';save();render();setTimeout(()=>showNewsPrompt(true),400);return;}
    renderOnboard();
  });
}
function pad(){return `<div class="pad">${[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map(k=>k===''?'<span></span>':`<button class="key${k==='⌫'?' ghost':''}" data-k="${k}">${k}</button>`).join('')}</div>`;}
function dots(n){return `<div class="dots">${[0,1,2,3].map(i=>`<i class="${i<n?'on':''}"></i>`).join('')}</div>`;}
function bindPad(f){$$('.pad button').forEach(b=>b.onclick=()=>f(b.dataset.k));}

/* ---------- login ---------- */
let pick=null,pinBuf='';
function renderLogin(){
  const us=DB.users;if(us.length===1&&!pick)pick=us[0].id;
  $('#root').innerHTML=`<div class="login"><div class="in">${DB.ws.logo?`<img class="logo" src="${DB.ws.logo}" alt="">`:`<div class="ob-hero"><span class="wsmark big">${esc(initials(DB.ws.name))}</span><h2 style="font:400 1.5rem var(--f-brand)">${esc(DB.ws.name)}</h2></div>`}
   <h2>Who is working today?</h2>
   <div class="people">${us.map(u=>`<button class="person${pick===u.id?' sel':''}" data-u="${u.id}"><span class="av" style="${pick===u.id?'':'background:'+u.color}">${initials(u.name)}</span>${esc(u.name)}<small>${ROLE[u.role]}</small></button>`).join('')}</div>
   ${pick?dots(pinBuf.length)+pad():'<p>Tap your name</p>'}<div class="err" id="err"></div></div></div>`;
  $$('.person').forEach(b=>b.onclick=()=>{pick=b.dataset.u;pinBuf='';renderLogin();});
  bindPad(async k=>{if(k==='⌫')pinBuf=pinBuf.slice(0,-1);else if(pinBuf.length<4)pinBuf+=k;
    if(pinBuf.length===4){const u=DB.users.find(x=>x.id===pick);const h=await hashPin(pinBuf);pinBuf='';if(u&&u.pin===h){S.user=u;S.r='home';render();setTimeout(showNewsPrompt,500);return;}renderLogin();$('#err').textContent='Wrong PIN. Try again.';return;}
    renderLogin();});
}

/* ---------- HOME ---------- */
const SCREENS={};
function carRow(j){const v=vehOf(j),c=custOf(j),T=jobTotals(j),[sl,sc]=STAGE[j.stage];
  const right=j.stage==='ready'&&T.due>0?`not paid · ${f3(T.due)}`:j.stage==='work'&&j.eta?`ready ~${hm(j.eta)}`:j.stage==='done'?f3(T.total):ago(j.t);
  return `<button class="car" data-go="job:${j.id}" style="--sc:${sc}"><div class="no">#${j.no}</div><div class="tx"><b>${esc(carName(v)||'Car')}${v.plate?` <span class="pl">${esc(v.plate)}</span>`:''}</b><span>${esc(c.name||'Walk-in')}${(j.items||[]).length?' · '+esc(j.items.slice(0,2).map(i=>i.d).join(' + ')):''}</span></div><div class="st">${sl.toUpperCase()}<small>${right}</small></div></button>`;}
SCREENS.home=m=>{
  const open=openJobs(),[pd,pt]=stepsProgress(),due=dueInvoices().reduce((a,j)=>a+jobTotals(j).due,0),low=lowParts().length,rem=remindersDue().length;
  const todayInv=DB.jobs.filter(j=>isInvoiced(j)&&dayKey(j.inv.t)===today());const est=DB.jobs.filter(j=>j.stage==='estimate');
  m.innerHTML=demoBanner()+`
  <button class="srch" data-go="search"><svg><use href="#i-list"/></svg><b>Plate, phone or name…</b></button>
  <button class="bigbtn" data-go="newjob"><div><b>New car in</b><span>Customer → car → services → invoice</span></div><span class="plus">＋</span></button>
  ${pd<pt?`<button class="setupbar" data-go="setup"><div><b>Setup · ${pd}/${pt} steps</b><span>Finish setting up your workshop</span></div><div class="ring" style="--p:${Math.round(pd/pt*100)}">${Math.round(pd/pt*100)}%</div></button>`:''}
  ${sec(`In the workshop now · ${open.length}`,open.length?'<a data-go="work">All ›</a>':'')}
  ${open.length?`<div class="list">${open.slice(0,4).map(carRow).join('')}</div>`:empty('🚗','No cars in the workshop. Tap <b>New car in</b> when one arrives.')}
  <div class="kpis3">${can.money()?`<button class="kpi org" data-go="money"><b>${f3(due)}</b><span>Due · ${DB.ws.currency}</span></button>`:''}<button class="kpi ${low?'red':''}" data-go="stock"><b>${low}</b><span>To order</span></button><button class="kpi" data-go="cust"><b>${rem}</b><span>Reminders</span></button></div>
  <div class="grp">
   <button class="g" data-go="work" style="--tc:#3a1a1a;--glow:rgba(238,58,57,.28)"><span class="ic">🔧</span><b>Work</b><div class="sub"><span><i>${open.length}</i> in workshop</span><span><i>${est.length}</i> estimates open</span><span><i>${todayInv.length}</i> invoices today</span></div></button>
   <button class="g" data-go="cust" style="--tc:#1a2a3a;--glow:rgba(37,99,201,.3)"><span class="ic">🚗</span><b>Customers</b><div class="sub"><span><i>${rem}</i> reminders due</span><span><i>${DB.customers.length}</i> customers</span><span><i>${DB.vehicles.length}</i> cars</span></div></button>
   <button class="g" data-go="stock" style="--tc:#3a2a10;--glow:rgba(242,123,33,.28)">${low?`<span class="n">${low}</span>`:''}<span class="ic">🛢</span><b>Stock</b><div class="sub"><span><i>${DB.parts.length}</i> parts</span><span><i>${low}</i> to order</span><span><i>${countToday().length}</i> to count today</span></div></button>
   ${can.money()?`<button class="g" data-go="money" style="--tc:#1a3a26;--glow:rgba(60,207,125,.26)"><span class="ic">💰</span><b>Money</b><div class="sub"><span><i>${f3(due)}</i> due</span><span><i>${f3(todayInv.reduce((a,j)=>a+jobTotals(j).total,0))}</i> today</span><span><i>${DB.expenses.length}</i> expenses</span></div></button>`:`<button class="g" data-go="count" style="--tc:#1a3a26;--glow:rgba(60,207,125,.26)"><span class="ic">📦</span><b>Count</b><div class="sub"><span><i>${countToday().length}</i> to count today</span></div></button>`}
  </div>
  <button class="morerow" data-go="more"><span>⋯</span><b>More</b><span>Services · Suppliers · Inspections · Reports · Settings</span></button>`;
  const dx=$('#demox');if(dx)dx.onclick=()=>confirmSheet('Remove all test data (everything with 🧪)? Your real data stays.','Remove test data',removeDemo);
};
/* ---------- SEARCH ---------- */
SCREENS.search=m=>{
  m.innerHTML=head('Search')+`<input class="field" id="sq" placeholder="Plate, phone, name, VIN or job #" value="${esc(S.q)}" autocomplete="off"><div id="sres"></div>`;
  const inp=$('#sq');const run=()=>{const q=inp.value.trim().toLowerCase();S.q=inp.value;const box=$('#sres');if(!q){box.innerHTML='';return;}
    const vs=DB.vehicles.filter(v=>[v.plate,v.vin,carName(v)].some(x=>(x||'').toLowerCase().includes(q)));
    const cs=DB.customers.filter(c=>[c.name,c.phone].some(x=>(x||'').toLowerCase().includes(q)));
    const js=DB.jobs.filter(j=>String(j.no)===q.replace('#','')||(j.inv&&String(j.inv.no)===q.replace('#','')));
    box.innerHTML=(js.length?sec('Jobs')+`<div class="list">${js.map(carRow).join('')}</div>`:'')+(cs.length?sec('Customers')+`<div class="list">${cs.map(custRow).join('')}</div>`:'')+(vs.length?sec('Cars')+`<div class="list">${vs.map(v=>{const c=byId('customers',v.cust)||{};return `<button class="row" data-go="custd:${v.cust}"><div><b>${esc(carName(v))} ${v.plate?`<span class="pl">${esc(v.plate)}</span>`:''}</b><span>${esc(c.name||'')}${v.km?' · '+kmf(v.km)+' km':''}</span></div><span class="v">›</span></button>`;}).join('')}</div>`:'')||empty('🔍','Nothing found.');
    box.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{const [r,id]=b.dataset.go.split(':');go(r,{id});});};
  inp.oninput=run;run();setTimeout(()=>inp.focus(),50);
};
/* ---------- WORK ---------- */
SCREENS.work=m=>{
  const f=S.p.f||'open';const cnt=k=>DB.jobs.filter(j=>k==='open'?(j.stage!=='done'&&j.stage!=='estimate'):k==='today'?(j.stage==='done'&&isInvoiced(j)&&dayKey(j.inv.t)===today()):j.stage===k).length;
  let list=DB.jobs.filter(j=>f==='open'?(j.stage!=='done'&&j.stage!=='estimate'):f==='today'?(j.stage==='done'&&isInvoiced(j)&&dayKey(j.inv.t)===today()):f==='all'?true:j.stage===f).sort((a,b)=>b.t-a.t);
  m.innerHTML=head('Work')+`<div class="pipe">${[['new','New'],['work','Working'],['ready','Ready'],['today','Done today']].map(([k,l])=>`<button data-f="${k}" class="${f===k?'on':''}"><b>${cnt(k)}</b><span>${l}</span></button>`).join('')}</div>
  <div class="chips">${[['open','Open'],['estimate','Estimates'],['done','Done'],['all','All']].map(([k,l])=>`<button data-f="${k}" aria-pressed="${f===k}">${l}<span>${cnt(k)}</span></button>`).join('')}</div>
  <button class="btn okb" data-go="newjob">＋ New car in</button>
  ${list.length?`<div class="list">${list.map(carRow).join('')}</div>`:empty('🔧','Nothing here.')}`;
  m.querySelectorAll('[data-f]').forEach(b=>b.onclick=()=>{S.p.f=b.dataset.f;render();});
};
/* ---------- NEW JOB (customer → car → job) ---------- */
SCREENS.newjob=m=>{
  const N=S.p.n||(S.p.n={phone:'',name:'',plate:'',make:'',model:'',year:'',km:'',vin:'',engine:'',est:false,custId:null,vehId:null});
  const found=N.phone.length>=4?DB.customers.filter(c=>(c.phone||'').includes(N.phone)).slice(0,4):[];
  const vfound=N.plate.length>=2?DB.vehicles.filter(v=>(v.plate||'').toLowerCase().includes(N.plate.toLowerCase())).slice(0,4):[];
  const cust=N.custId&&byId('customers',N.custId);const cars=cust?DB.vehicles.filter(v=>v.cust===cust.id):[];
  m.innerHTML=head('New car in')+`
  <div class="steps3"><span class="on">1 Customer</span><span class="${cust?'on':''}">2 Car</span><span>3 Services</span></div>
  ${sec('Customer')}
  ${cust?`<div class="card sel"><div class="h"><b>${esc(cust.name)}</b><button class="lnk" id="nchg">Change</button></div><span class="sub">${esc(cust.phone||'')} · ${cars.length} car${cars.length===1?'':'s'}</span></div>`
  :`<div class="in2"><input class="field" id="nphone" inputmode="tel" placeholder="Phone" value="${esc(N.phone)}"><input class="field" id="nname" placeholder="Name" value="${esc(N.name)}"></div>
   ${found.length?`<div class="list">${found.map(c=>`<button class="row" data-pc="${c.id}"><div><b>${esc(c.name)}</b><span>${esc(c.phone)} · known customer</span></div><span class="v">Use ›</span></button>`).join('')}</div>`:''}
   <button class="btn ghost sm" id="nwalk">Walk-in (no name)</button>`}
  ${sec('Car')}
  ${cars.length&&!N.vehNew?`<div class="list">${cars.map(v=>`<button class="row${N.vehId===v.id?' selr':''}" data-pv="${v.id}"><div><b>${esc(carName(v))} ${v.plate?`<span class="pl">${esc(v.plate)}</span>`:''}</b><span>${v.km?'last '+kmf(v.km)+' km':''}</span></div><span class="v">${N.vehId===v.id?'✓':'›'}</span></button>`).join('')}<button class="row" id="nvnew"><div><b>＋ Another car</b></div></button></div>`
  :`<div class="in2"><input class="field" id="nplate" placeholder="Plate (12345 A)" value="${esc(N.plate)}" style="text-transform:uppercase"><input class="field" id="nkm" inputmode="numeric" placeholder="Km now" value="${esc(N.km)}"></div>
   ${vfound.length&&!cust?`<div class="list">${vfound.map(v=>{const c=byId('customers',v.cust)||{};return `<button class="row" data-pvf="${v.id}"><div><b>${esc(carName(v))} <span class="pl">${esc(v.plate)}</span></b><span>${esc(c.name||'')} · known car</span></div><span class="v">Use ›</span></button>`;}).join('')}</div>`:''}
   <button class="carpick" id="ncp">${N.make?`<b>${esc([N.make,N.model,N.year].filter(Boolean).join(' '))}</b><span>${N.engine?esc(N.engine):'Tap to choose the engine'}</span>`:'<b>🚗 Choose make, model, year, engine</b><span>Type “toy” for Toyota…</span>'}<em>›</em></button>
   <input type="hidden" id="nmake" value="${esc(N.make)}"><input type="hidden" id="nmodel" value="${esc(N.model)}"><input type="hidden" id="nyear" value="${esc(N.year)}">
   <input class="field" id="nvin" placeholder="VIN (optional)" maxlength="17" value="${esc(N.vin)}" style="text-transform:uppercase">`}
  ${N.vehId?`<input class="field" id="nkm2" inputmode="numeric" placeholder="Km now" value="${esc(N.km)}">`:''}
  <label class="chk"><input type="checkbox" id="nest" ${N.est?'checked':''}> Estimate only (customer has not agreed yet)</label>
  <button class="btn" id="ngo">Open ${N.est?'estimate':'job card'} ›</button>`;
  const keep=()=>{['nphone','nname','nplate','nkm','nmake','nmodel','nyear','nvin','nkm2'].forEach(id=>{const e=$('#'+id);if(e)N[{nphone:'phone',nname:'name',nplate:'plate',nkm:'km',nmake:'make',nmodel:'model',nyear:'year',nvin:'vin',nkm2:'km'}[id]]=e.value;});};
  ['nphone','nplate'].forEach(id=>{const e=$('#'+id);if(e)e.oninput=()=>{keep();const pos=e.value.length;render();const e2=$('#'+id);e2.focus();try{e2.setSelectionRange(pos,pos);}catch(x){}};});
  $$('[data-pc]').forEach(b=>b.onclick=()=>{keep();N.custId=b.dataset.pc;const vs=DB.vehicles.filter(v=>v.cust===N.custId);N.vehId=vs.length===1?vs[0].id:null;render();});
  $$('[data-pv]').forEach(b=>b.onclick=()=>{keep();N.vehId=b.dataset.pv;render();});
  $$('[data-pvf]').forEach(b=>b.onclick=()=>{keep();const v=byId('vehicles',b.dataset.pvf);N.custId=v.cust;N.vehId=v.id;render();});
  const ncp=$('#ncp');if(ncp)ncp.onclick=()=>{keep();carPicker(N,r=>{Object.assign(N,r);render();});};
  const nv=$('#nvnew');if(nv)nv.onclick=()=>{keep();N.vehNew=true;N.vehId=null;render();};
  const ch=$('#nchg');if(ch)ch.onclick=()=>{N.custId=null;N.vehId=null;N.vehNew=false;render();};
  const wk=$('#nwalk');if(wk)wk.onclick=()=>{keep();N.name='Walk-in';render();};
  $('#nest').onchange=e=>{keep();N.est=e.target.checked;render();};
  $('#ngo').onclick=()=>{keep();
    let c=cust;if(!c){if(!N.name&&!N.phone){toast('Type a phone or name, or tap Walk-in');return;}c={id:uid('c'),name:N.name||'Walk-in',phone:N.phone.replace(/[^\d+]/g,''),t:now()};DB.customers.push(c);}
    let v=N.vehId&&byId('vehicles',N.vehId);
    if(!v){if(!N.make&&!N.plate){toast('Type the plate or the make');return;}v={id:uid('v'),cust:c.id,make:N.make.trim(),model:N.model.trim(),year:N.year.trim(),plate:N.plate.trim().toUpperCase(),vin:N.vin.trim().toUpperCase(),engine:N.engine||'',km:num(N.km),t:now()};DB.vehicles.push(v);}
    else if(num(N.km))v.km=num(N.km);
    const j={id:uid('j'),no:DB.ws.nextJob++,cust:c.id,veh:v.id,km:num(N.km)||v.km||0,stage:N.est?'estimate':'new',items:[],disc:0,t:now(),by:S.user.name,log:[[now(),(N.est?'Estimate':'Job')+' opened · '+S.user.name]],pays:[]};
    DB.jobs.push(j);save();toast((N.est?'Estimate':'Job')+' #'+j.no+' opened');go('job',{id:j.id});};
};

/* ---------- JOB ---------- */
const NEXT={estimate:['new','Customer agreed → job card'],new:['work','Start work'],work:['ready','Car is ready'],ready:['done','Delivered']};
function logJ(j,t){j.log.push([now(),t+' · '+S.user.name]);}
SCREENS.job=m=>{
  const j=byId('jobs',S.p.id);if(!j){go('work');return;}
  const v=vehOf(j),c=custOf(j),T=jobTotals(j),[sl,sc]=STAGE[j.stage];const nx=NEXT[j.stage];
  const stages=['new','work','ready','done'];const si=stages.indexOf(j.stage);
  m.innerHTML=head((j.stage==='estimate'?'Estimate':'Job')+' #'+j.no,`<span class="tag" style="background:${sc};color:#000">${sl}</span>`)+`
  <div class="card"><div class="h"><b>${esc(carName(v)||'Car')} ${v.plate?`<span class="pl">${esc(v.plate)}</span>`:''}</b><button class="lnk" data-go="custd:${c.id}">${esc(c.name||'')} ›</button></div>
   <span class="sub">${v.engine?'⚙️ '+esc(v.engine)+'<br>':''}${c.phone?esc(c.phone)+' · ':''}${j.km?kmf(j.km)+' km · ':''}opened ${hm(j.t)} by ${esc(j.by)}${j.eta&&j.stage==='work'?' · ready ~'+hm(j.eta):''}</span></div>
  ${j.stage!=='estimate'?`<div class="jb-steps">${stages.map((s,i)=>`<div class="${i<=si?'on':''}" style="--sc:${STAGE[s][1]}"><i></i><span>${STAGE[s][0]}</span></div>`).join('')}</div>`:''}
  ${nx?`<button class="btn okb" id="jnext">${nx[1]}</button>`:''}
  ${sec('Services & parts',`${(j.items||[]).length} items`)}
  <div class="jb-list">${(j.items||[]).map((it,i)=>`<button class="jb-r it${it.pend?' pend':''}" data-it="${i}"><div>${esc(it.d)}<small>${it.k==='part'?'Part':'Labour'}${it.num?' · '+esc(it.num):''}${it.q!==1||it.u?' · '+(+it.q)+(it.u?' '+esc(it.u):'')+' × '+f3(it.p):''}${it.outside?' · bought outside':''}</small></div><b>${it.pend?'Price?':f3(it.q*it.p)}</b></button>`).join('')}
   ${!isInvoiced(j)?`<button class="jb-r add" id="jadd"><div>＋ Add service or part</div></button>`:''}
   ${T.disc?`<div class="jb-r"><div>Discount${j.discPct?` (${j.discPct}%)`:''}</div><b>−${f3(T.disc)}</b></div>`:''}
   <div class="jb-r tot"><div>Total<small>Parts ${f3(T.parts)} · Labour ${f3(T.labour)}${can.cost()&&T.parts?` · profit ${f3(T.profit)}`:''}</small></div><b>${f3(T.total)} ${DB.ws.currency}</b></div></div>
  ${!isInvoiced(j)&&can.discount()?`<button class="btn ghost sm" id="jdisc">Discount</button>`:''}
  ${sec('Inspection',j.insp?`${Object.values(j.insp.r||{}).filter(x=>x==='bad').length} red · ${Object.values(j.insp.r||{}).filter(x=>x==='warn').length} yellow`:'')}
  ${j.insp?`<button class="row" id="jinsp"><div><b>${esc(j.insp.name)}</b><span>${Object.keys(j.insp.r||{}).length}/${j.insp.items.length} checked</span></div><span class="v">Open ›</span></button>`:`<button class="btn ghost sm" id="jinsp">＋ Start an inspection</button>`}
  <label class="field-l">Notes<textarea class="field" id="jnotes" rows="2" placeholder="What the customer said, what we found…">${esc(j.notes||'')}</textarea></label>
  <div class="two">${j.stage==='estimate'?`<button class="btn ghost" id="jsendest">📤 Send estimate</button>`:isInvoiced(j)?`<button class="btn ghost" data-go="inv:${j.id}">🧾 Invoice #${j.inv.no}</button>`:can.invoice()?`<button class="btn ghost" id="jinv">🧾 Make invoice</button>`:`<span></span>`}
   <button class="btn ghost" id="jstk">🏷️ Sticker</button></div>
  ${c.phone&&(j.stage==='ready'||j.stage==='done')?`<button class="btn wa" id="jwa">WhatsApp: car is ready</button>`:''}
  ${sec('Timeline')}<div class="jb-log">${j.log.slice().reverse().map(l=>`<div><span>${hm(l[0])}</span>${esc(l[1])}</div>`).join('')}</div>
  ${can.del()&&!isInvoiced(j)?`<button class="btn ghost jb-del" id="jdel">Delete ${j.stage==='estimate'?'estimate':'job'}</button>`:''}`;
  const nb=$('#jnext');if(nb)nb.onclick=()=>{
    if(j.stage==='estimate'){j.stage='new';j.fromEst=true;logJ(j,'Customer agreed');save();render();return;}
    if(j.stage==='new'){const mins=(j.items||[]).reduce((a,i)=>a+(+i.min||0)*(i.k==='part'?0:Math.max(1,Math.round(+i.q||1))),0);openSheet(`<h3>How long will it take?</h3>${mins?`<p class="hint">The services on this job take about <b>${mins>=60?Math.floor(mins/60)+' h '+(mins%60?mins%60+' min':''):mins+' min'}</b>.</p>`:''}<div class="chips big">${mins?`<button data-eta="${mins}">≈ ${mins>=60?(Math.round(mins/6)/10)+' h':mins+' min'} (services)</button>`:''}${[[30,'30 min'],[60,'1 hour'],[120,'2 hours'],[180,'3 hours'],[1440,'Tomorrow']].map(([x,l])=>`<button data-eta="${x}">${l}</button>`).join('')}</div>`,el=>el.querySelectorAll('[data-eta]').forEach(b=>b.onclick=()=>{const x=+b.dataset.eta;j.eta=x>=1440?new Date(new Date().setHours(33,0,0,0)).getTime():now()+x*60e3;j.stage='work';logJ(j,'Working · ETA '+b.textContent);save();closeSheet();render();}));return;}
    if(j.stage==='ready'&&!isInvoiced(j)&&can.invoice()){toast('Make the invoice first');return;}
    j.stage=nx[0];logJ(j,STAGE[nx[0]][0]);if(j.stage==='done')makeReminders(j);save();render();};
  const ad=$('#jadd');if(ad)ad.onclick=()=>addItemSheet(j);
  $$('[data-it]').forEach(b=>b.onclick=()=>{if(isInvoiced(j)){toast('Invoice made. Return it to change items.');return;}editItemSheet(j,+b.dataset.it);});
  const ds=$('#jdisc');if(ds)ds.onclick=()=>openSheet(`<h3>Discount</h3><div class="in2"><input class="field" id="dam" inputmode="decimal" placeholder="Amount (${DB.ws.currency})" value="${j.discPct?'':j.disc||''}"><input class="field" id="dpc" inputmode="decimal" placeholder="or %" value="${j.discPct||''}"></div><button class="btn" id="dok">Save</button>`,el=>el.querySelector('#dok').onclick=()=>{const p=num($('#dpc').value),a=num($('#dam').value);j.discPct=p||0;j.disc=p?0:a;logJ(j,'Discount '+(p?p+'%':f3(a)));save();closeSheet();render();});
  $('#jnotes').onchange=e=>{j.notes=e.target.value;save();};
  $('#jinsp').onclick=()=>{if(j.insp)inspSheet(j);else openSheet(`<h3>Choose a checklist</h3><div class="list">${DB.insp.map(t=>`<button class="row" data-ti="${t.id}"><div><b>${esc(t.name)}</b><span>${t.items.length} items</span></div><span class="v">›</span></button>`).join('')}</div>`,el=>el.querySelectorAll('[data-ti]').forEach(b=>b.onclick=()=>{const t=DB.insp.find(x=>x.id===b.dataset.ti);j.insp={name:t.name,items:t.items.slice(),r:{}};logJ(j,'Inspection started');save();inspSheet(j);}));};
  const se=$('#jsendest');if(se)se.onclick=()=>shareText(c.phone,docText(j,'estimate'));
  const iv=$('#jinv');if(iv)iv.onclick=()=>makeInvoice(j);
  $('#jstk').onclick=()=>stickerSheet(j);
  const wa=$('#jwa');if(wa)wa.onclick=()=>shareText(c.phone,msg('ready',jobVars(j)));
  const dl=$('#jdel');if(dl)dl.onclick=()=>confirmSheet('Delete '+(j.stage==='estimate'?'estimate':'job')+' #'+j.no+'?','Delete',()=>{DB.jobs=DB.jobs.filter(x=>x!==j);save();go('work');});
};
function shareText(phone,t){const u='https://wa.me/'+(phone?waNum(phone):'')+'?text='+encodeURIComponent(t);try{location.href=u;}catch(e){}if(navigator.clipboard)navigator.clipboard.writeText(t).catch(()=>{});}
function jobVars(j){const v=vehOf(j),c=custOf(j),T=jobTotals(j);const cur=DB.ws.currency==='OMR'?'ر.ع':DB.ws.currency;
  return {name:c.name||'',car:carName(v),plate:v.plate||'',no:j.inv&&!j.inv.void?j.inv.no:j.no,date:fmtD(j.inv?j.inv.t:j.t),
    items:(j.items||[]).filter(i=>!i.pend).map(i=>'• '+(i.ar||i.d)+(i.q!==1||i.u?' '+(+i.q)+(i.u?' '+i.u:'')+' × '+f3(i.p):'')+': '+f3(i.q*i.p)).join('\n')+(T.disc?'\nخصم: −'+f3(T.disc):''),
    total:f3(T.total)+' '+cur,paid:f3(T.paid)+' '+cur,due:f3(T.due)+' '+cur,km:j.km?kmf(j.km):'',warranty:DB.ws.warranty||''};}
function docText(j,kind){const x=jobVars(j);if(kind==='estimate')x.no=j.no;return msg(kind,x);}
/* add / edit items */
function svcUse(){const u={};DB.jobs.forEach(j=>(j.items||[]).forEach(i=>{if(i.ref)u[i.ref]=(u[i.ref]||0)+1;}));return u;}
function svcItem(s,v){return {k:'labour',ref:s.id,d:s.name,ar:s.ar||'',q:1,u:'',p:svcPrice(s,v),tag:s.tag,war:s.war||'',min:+s.min||0,comm:+s.comm||0,by:S.user.name,lockP:!!s.lockP,from:!!s.from,out:s.out&&s.out.who?Object.assign({},s.out):null};}
function addItemSheet(j){
  let q='';const v=vehOf(j);const use=svcUse();
  const draw=el=>{const ql=q.toLowerCase();const f=x=>!ql||x.toLowerCase().includes(ql);const sz=sizeOf(v);
    el.querySelector('#asz').innerHTML=DB.sizes.map((n,k)=>`<button data-sz="${k}" aria-pressed="${k===sz}">${esc(n)}</button>`).join('');
    const sv=DB.services.filter(s=>!s.hidden&&f(s.name+' '+(s.ar||'')+' '+s.cat)).sort((a,b)=>(use[b.id]||0)-(use[a.id]||0));const ps=DB.parts.filter(p=>f(p.name+' '+(p.num||'')+' '+p.cat));const cj=DB.canned.filter(c=>f(c.name));
    el.querySelector('#alist').innerHTML=
     (cj.length?`<div class="lbl">Canned jobs</div>`+cj.map(c=>`<button class="opt" data-cj="${c.id}"><div class="tx"><b>${esc(c.name)}</b><span>${c.items.length} items</span></div><span class="v">${f3(c.items.reduce((a,i)=>a+i.q*i.p,0))}</span></button>`).join(''):'')+
     (sv.length?`<div class="lbl">Services${!ql&&Object.keys(use).length?' · most used first':''}</div>`+sv.slice(0,ql?60:16).map(s=>`<button class="opt" data-sv="${s.id}"><div class="tx"><b>${scatIc(s.cat)} ${esc(s.name)}</b><span>${esc(s.cat)}${s.min?' · '+s.min+' min':''}${s.out&&s.out.who?' · at '+esc(s.out.who):''}${(s.parts||[]).length?' · + '+s.parts.length+' parts':''}</span></div><span class="v">${s.from?'<small>from</small>':''}${f3(svcPrice(s,v))}</span></button>`).join(''):'')+
     (ps.length?`<div class="lbl">Parts</div>`+partOpts(v,ps):DB.parts.length?'':`<p class="hint">No parts yet. Add them in Stock, or use “Something else”.</p>`);
    el.querySelectorAll('[data-sz]').forEach(b=>b.onclick=()=>{v.size=+b.dataset.sz;save();draw(el);});
    el.querySelectorAll('[data-sv]').forEach(b=>b.onclick=()=>{const s=byId('services',b.dataset.sv);if(smartOk(s)){smartSheet(j,s);return;}j.items.push(svcItem(s,v));const at=j.items.length-1;
      (s.parts||[]).forEach(x=>{const pt=byId('parts',x.ref);if(pt)j.items.push({k:'part',ref:pt.id,d:pt.name,num:pt.num,q:+x.q||1,u:pt.unit==='L'?'L':'',p:+pt.price,cost:+pt.cost||0});});
      logJ(j,'Added '+s.name);save();if(s.from){editItemSheet(j,at);return;}closeSheet();render();});
    el.querySelectorAll('[data-pt]').forEach(b=>b.onclick=()=>{const p=byId('parts',b.dataset.pt);j.items.push({k:'part',ref:p.id,d:p.name,num:p.num,q:1,u:p.unit==='L'?'L':'',p:+p.price,cost:+p.cost||0});save();editItemSheet(j,j.items.length-1,true);});
    el.querySelectorAll('[data-cj]').forEach(b=>b.onclick=()=>{const c=DB.canned.find(x=>x.id===b.dataset.cj);c.items.forEach(i=>j.items.push(Object.assign({},i)));logJ(j,'Added '+c.name);save();closeSheet();render();});};
  openSheet(`<h3>Add to ${j.stage==='estimate'?'estimate':'job'} #${j.no}</h3><div class="field-l">Car size</div><div class="chips" id="asz"></div><div class="srow"><input class="field" id="aq" placeholder="Search services and parts" autocomplete="off">${sx('scan')?'<button class="scanb" id="ascan">📷</button>':''}</div><button class="btn ghost sm" id="acust">✏️ Something else (type name and price)</button><div id="alist"></div>`,el=>{
    el.querySelector('#aq').oninput=e=>{q=e.target.value;draw(el);};const asc=el.querySelector('#ascan');if(asc)asc.onclick=()=>scanSheet(c=>{const p=findByCode(c);if(!p){toast('No part with '+c);return;}j.items.push({k:'part',ref:p.id,d:p.name,num:p.num,q:1,u:p.unit==='L'?'L':'',p:+p.price,cost:+p.cost||0});save();editItemSheet(j,j.items.length-1,true);});
    el.querySelector('#acust').onclick=()=>{j.items.push({k:'part',d:'',q:1,u:'',p:0,cost:0,neu:1,by:S.user.name});editItemSheet(j,j.items.length-1,true);};
    draw(el);});
}
const isSuv=v=>/land cruiser|patrol|prado|fortuner|pajero|tahoe|yukon|suburban|lx|gx|range|x5|x7|gle|q7|explorer|expedition|sequoia|armada|4runner|fj|tundra|sierra|silverado|ram|f-150/i.test((v&&v.model)||'');
const isPickup=v=>/hilux|pickup|pick-up|navara|d-max|dmax|l200|triton|ranger|tacoma/i.test((v&&v.model)||'');
function sizeOf(v){const n=DB.sizes.length;if(v&&v.size!=null&&v.size<n)return v.size;const g=x=>{const i=DB.sizes.findIndex(s=>s.toLowerCase()===x);return i<0?null:i;};
  if(isPickup(v)&&g('pickup')!=null)return g('pickup');if(isSuv(v)&&g('suv')!=null)return g('suv');return g('sedan')!=null?g('sedan'):0;}
function svcPrice(s,v){const k=sizeOf(v);const p=s.p||[0];return +(p[k]!=null&&p[k]!==''?p[k]:p[p.length-1])||0;}
function editItemSheet(j,i,isNew){
  const it=j.items[i];if(!it)return;
  openSheet(`<h3>${isNew&&!it.ref?'New item':'Item'}</h3>
   <input class="field" id="ed" placeholder="Name" value="${esc(it.d)}">
   <div class="chips"><button data-k="part" aria-pressed="${it.k==='part'}">Part</button><button data-k="labour" aria-pressed="${it.k!=='part'}">Labour / service</button></div>
   <div class="in2"><label class="field-l">Qty${it.u?' ('+esc(it.u)+')':''}<input class="field" id="eq" inputmode="decimal" value="${+it.q}"></label><label class="field-l">Price each${it.from?' (starts from '+f3(it.p)+')':''}<input class="field" id="ep" inputmode="decimal" value="${it.pend?'':f3(it.p)}" ${it.lockP&&!can.discount()?'disabled':''}></label></div>
   ${can.cost()&&it.k==='part'?`<label class="field-l">Cost each (owner only)<input class="field" id="ec" inputmode="decimal" value="${it.cost?f3(it.cost):''}"></label>`:''}
   ${!it.ref?`<label class="chk"><input type="checkbox" id="eo" ${it.outside?'checked':''}> Bought outside (not from our stock)</label>`:''}
   <label class="chk"><input type="checkbox" id="epd" ${it.pend?'checked':''}> Ask the owner for the price</label>
   <button class="btn" id="eok">Save</button><button class="btn ghost jb-del" id="edel">Remove</button>`,el=>{
    let k=it.k;el.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{k=b.dataset.k;el.querySelectorAll('[data-k]').forEach(x=>x.setAttribute('aria-pressed',x===b));});
    el.querySelector('#eok').onclick=()=>{const d=$('#ed').value.trim();if(!d){toast('Type a name');return;}it.d=d;it.k=k;it.q=num($('#eq').value)||1;it.pend=$('#epd').checked;it.p=it.pend?0:num($('#ep').value);const ec=$('#ec');if(ec)it.cost=num(ec.value);const eo=$('#eo');if(eo)it.outside=eo.checked;
      if(!can.discount()&&it.ref){const base=it.k==='part'?(byId('parts',it.ref)||{}).price:null;if(base!=null&&it.p<+base-0.0005){it.p=+base;toast('Workers cannot lower prices');}}
      logJ(j,(it.neu?'Added ':'Changed ')+d+(it.pend?' (price pending)':' '+f3(it.q*it.p)));delete it.neu;save();closeSheet();render();};
    el.querySelector('#edel').onclick=()=>{j.items.splice(i,1);logJ(j,'Removed '+(it.d||'item'));save();closeSheet();render();};
    el.querySelector('[data-close]').onclick=()=>{if(it.neu)j.items.splice(i,1);closeSheet();render();};});
}
/* inspection */
function inspSheet(j){const I=j.insp;
  openSheet(`<h3>${esc(I.name)}</h3><p class="hint">Green = good · Yellow = soon · Red = now</p><div class="insp">${I.items.map((x,i)=>`<div class="ir"><span>${esc(x)}</span><div>${['ok','warn','bad'].map(s=>`<button data-ir="${i}:${s}" class="s-${s}${I.r[i]===s?' on':''}"></button>`).join('')}</div></div>`).join('')}</div>
   <button class="btn" id="iok">Done</button>`,el=>{el.querySelectorAll('[data-ir]').forEach(b=>b.onclick=()=>{const [i,s]=b.dataset.ir.split(':');I.r[i]=I.r[i]===s?undefined:s;if(!I.r[i])delete I.r[i];save();el.querySelectorAll(`[data-ir^="${i}:"]`).forEach(x=>x.classList.toggle('on',x.dataset.ir===i+':'+I.r[i]));});
    el.querySelector('#iok').onclick=()=>{const red=Object.entries(I.r).filter(([,s])=>s==='bad').map(([i])=>I.items[i]);if(red.length)logJ(j,'Inspection: red '+red.join(', '));save();closeSheet();render();};});}
/* invoice */
function makeInvoice(j){
  const T=jobTotals(j);if(!(j.items||[]).length){toast('Add services or parts first');return;}
  if((j.items||[]).some(i=>i.pend)){toast('Some items have no price yet');return;}
  confirmSheet(`Make invoice for ${f3(T.total)} ${DB.ws.currency}?<br><small class="hint">Parts from stock will be taken out of the stock.</small>`,'Make invoice',()=>{
    j.inv={no:DB.ws.nextInv++,t:now(),by:S.user.name};(j.items||[]).forEach(it=>{if(it.k==='part'&&it.ref){const p=byId('parts',it.ref);if(p)mv(p,-(+it.q||0),'Invoice #'+j.inv.no,j.id);}});
    if(j.stage==='new'||j.stage==='work')j.stage='ready';logJ(j,'Invoice #'+j.inv.no);save();go('inv',{id:j.id});});
}
SCREENS.inv=m=>{
  const j=byId('jobs',S.p.id);if(!j||!j.inv){go('work');return;}const T=jobTotals(j),c=custOf(j);
  m.innerHTML=head('Invoice #'+j.inv.no,j.returned?'<span class="tag t-bad">Returned</span>':T.due<=0.0005?'<span class="tag t-ok">Paid</span>':`<span class="tag t-warn">Due ${f3(T.due)}</span>`)+`
  <div class="inv-pv">${invoiceHtml(j)}</div>
  ${!j.returned&&T.due>0.0005&&can.money()?`${sec('Take payment',`due ${f3(T.due)}`)}<div class="chips big">${DB.ws.pay.map(p=>`<button data-pay="${esc(p)}">${esc(p)}</button>`).join('')}</div>`:''}
  ${(j.pays||[]).length?sec('Payments')+`<div class="jb-list">${j.pays.map(p=>`<div class="jb-r"><div>${esc(p.m)}<small>${fmtD(p.t)} ${hm(p.t)} · ${esc(p.by)}</small></div><b>${f3(p.amt)}</b></div>`).join('')}</div>`:''}
  <div class="two"><button class="btn" id="iwa">WhatsApp</button><button class="btn ghost" id="ipr">🖨 Print</button></div>
  <button class="btn ghost" data-go="job:${j.id}">Back to the job</button>
  ${can.del()&&!j.returned?`<button class="btn ghost jb-del" id="iret">Return / cancel invoice</button>`:''}`;
  $$('[data-pay]').forEach(b=>b.onclick=()=>{const mth=b.dataset.pay;openSheet(`<h3>${esc(mth)}</h3><input class="field" id="pam" inputmode="decimal" value="${f3(T.due)}"><button class="btn" id="pok">Save payment</button>`,el=>el.querySelector('#pok').onclick=()=>{const a=Math.min(num($('#pam').value),T.due);if(a<=0)return;j.pays.push({m:mth,amt:a,t:now(),by:S.user.name});logJ(j,'Paid '+f3(a)+' · '+mth);save();closeSheet();render();});});
  $('#iwa').onclick=()=>shareText(c.phone,docText(j,'invoice'));
  $('#ipr').onclick=()=>printHtml('<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:14mm}body{margin:0;font-family:Arial,sans-serif}'+INV_CSS+'</style></head><body>'+invoiceHtml(j,true)+'</body></html>',210,297,'Invoice '+j.inv.no);
  const rt=$('#iret');if(rt)rt.onclick=()=>confirmSheet('Return invoice #'+j.inv.no+'? Parts go back to stock.','Return',()=>{(j.items||[]).forEach(it=>{if(it.k==='part'&&it.ref){const p=byId('parts',it.ref);if(p)mv(p,+it.q||0,'Return of invoice #'+j.inv.no,j.id);}});j.returned=now();j.inv.void=true;j.pays=[];j.stage='done';logJ(j,'Invoice returned');save();render();});
};
function invoiceHtml(j,print){const v=vehOf(j),c=custOf(j),T=jobTotals(j);let n=0;
  const tr=k=>(j.items||[]).filter(i=>(k==='part'?i.k==='part':i.k!=='part')&&!i.pend).map(i=>{n++;return `<tr><td class="n">${n}</td><td>${esc(i.d)}${i.num?`<small>${esc(i.num)}</small>`:''}${i.ar?`<div class="ar" style="font-size:2.7mm;color:#444">${esc(i.ar)}</div>`:''}${i.war?`<div style="font-size:2.4mm;color:#555">Warranty: ${esc(i.war)}</div>`:''}</td><td class="q">${+i.q}${i.u?' '+esc(i.u):''}</td><td class="u">${f3(i.p)}</td><td class="a">${f3(i.q*i.p)}</td></tr>`;}).join('');
  const pa=tr('part'),la=tr('labour');
  return `<div class="inv"><div class="inv-hd">${DB.ws.logo?`<img src="${DB.ws.logo}" alt="">`:`<b style="font-size:6mm">${esc(DB.ws.name)}</b>`}<div class="inv-ws"><b>${esc(DB.ws.name)}</b><span>${[DB.ws.addr,DB.ws.phone,DB.ws.cr?'CR '+DB.ws.cr:''].filter(Boolean).map(esc).join(' · ')}</span></div></div>
  <div class="inv-ttl"><b>INVOICE <span class="ar">فاتورة</span></b><span>#${j.inv.no} · ${fmtD(j.inv.t)}</span></div>
  <div class="inv-meta"><div><small>Customer</small>${esc(c.name||'—')}</div><div><small>Phone</small>${esc(c.phone||'—')}</div><div><small>Car</small>${esc(carName(v)||'—')}</div><div><small>Plate</small>${esc(v.plate||'—')}</div><div><small>Km</small>${j.km?kmf(j.km):'—'}</div><div><small>VIN</small><span class="mono">${esc(v.vin||'—')}</span></div></div>
  <table class="inv-t"><thead><tr><th>#</th><th>Description</th><th class="q">Qty</th><th class="u">Unit</th><th class="a">${DB.ws.currency}</th></tr></thead><tbody>${pa?`<tr class="grp"><td colspan="5">Parts · <span class="ar0">قطع</span></td></tr>${pa}`:''}${la?`<tr class="grp"><td colspan="5">Labour · <span class="ar0">أجرة</span></td></tr>${la}`:''}</tbody></table>
  <div class="inv-sum">${T.parts&&T.labour?`<div><span>Parts</span><span>${f3(T.parts)}</span></div><div><span>Labour</span><span>${f3(T.labour)}</span></div>`:''}${T.disc?`<div><span>Discount · خصم</span><span>−${f3(T.disc)}</span></div>`:''}<div class="tot"><span>Total <span class="ar">المجموع</span></span><span>${f3(T.total)} ${DB.ws.currency}</span></div>${T.paid?`<div><span>Paid</span><span>${f3(T.paid)}</span></div><div><span>Due</span><span>${f3(T.due)}</span></div>`:''}</div>
  ${j.returned?'<div class="inv-paid">RETURNED · مرتجع</div>':T.due<=0.0005&&T.total>0?`<div class="inv-paid">PAID · مدفوع</div>`:''}
  <div class="inv-ft">${esc(DB.ws.warranty||'Thank you · شكراً لزيارتكم')}</div></div>`;}
function printHtml(doc,w,h,name){const P=window.Capacitor&&window.Capacitor.Plugins&&window.Capacitor.Plugins.FswPrint;
  if(P){P.printHtml({html:doc,widthMm:w,heightMm:h,name}).catch(e=>toast('Could not print: '+(e&&e.message||e)));return;}
  const f=document.createElement('iframe');f.style.cssText='position:fixed;width:0;height:0;border:0';document.body.appendChild(f);f.contentDocument.open();f.contentDocument.write(doc);f.contentDocument.close();setTimeout(()=>{try{f.contentWindow.print();}catch(e){}setTimeout(()=>f.remove(),1000);},300);}
/* reminders */
function makeReminders(j){const v=vehOf(j);(j.items||[]).forEach(it=>{const s=it.ref&&byId('services',it.ref);const tag=it.tag||(s&&s.tag)||'';
  if(tag==='oil'||tag==='gear'){const mo=tag==='gear'?36:(+DB.ws.remMonths||6),km=tag==='gear'?70000:(+it.nextKm||+DB.ws.remKm||7000);const d=new Date(j.inv?j.inv.t:now());d.setMonth(d.getMonth()+mo);
    DB.reminders=DB.reminders.filter(r=>!(r.veh===v.id&&r.kind===tag));DB.reminders.push({id:uid('r'),veh:v.id,cust:j.cust,kind:tag,due:d.getTime(),dueKm:j.km?j.km+km:0,job:j.id,sent:0});}});}
function remindersDue(){const t=now(),D=864e5;return DB.reminders.filter(r=>!r.sent&&r.due<=t+7*D&&r.due>=t-31*D);}
/* sticker */
function stickerSheet(j){const v=vehOf(j);const has=k=>(j.items||[]).some(i=>(i.tag||'')===k);let kind=has('gear')&&!has('oil')?'gear':'oil';
  let step=kind==='gear'?70000:(((j.items||[]).find(i=>i.nextKm)||{}).nextKm||(+DB.ws.remKm||7000));
  const draw=el=>{const d=new Date();d.setMonth(d.getMonth()+(kind==='gear'?36:(+DB.ws.remMonths||6)));el.querySelector('#spv').innerHTML=stickerHtml(kind,j.km,j.km?j.km+step:0,d.getTime());
    el.querySelector('#sst').innerHTML=(kind==='gear'?[40000,50000,60000,70000,80000]:[5000,7000,10000]).map(x=>`<button data-s="${x}" aria-pressed="${step===x}">+${x>=40000?x/1000+'k':kmf(x)} km</button>`).join('');
    el.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{step=+b.dataset.s;draw(el);});el.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.kind===kind));};
  openSheet(`<h3>Service sticker</h3><div class="chips"><button data-kind="oil">Engine oil</button><button data-kind="gear">Gearbox oil</button></div><div class="stk-pv" id="spv"></div><div class="chips" id="sst"></div>${j.km?'':`<p class="hint">Add the km on the job to print the next km.</p>`}<button class="btn" id="sgo">🖨 Print sticker</button><p class="hint">In the print screen pick paper 2.4" x 39" (62 mm roll).</p>`,el=>{
    el.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;step=kind==='gear'?70000:(+DB.ws.remKm||7000);draw(el);});draw(el);
    el.querySelector('#sgo').onclick=()=>{const d=new Date();d.setMonth(d.getMonth()+(kind==='gear'?36:(+DB.ws.remMonths||6)));printHtml('<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:0}html,body{margin:0;background:#fff}'+STK_CSS+'</style></head><body>'+stickerHtml(kind,j.km,j.km?j.km+step:0,d.getTime())+'</body></html>',62,990,'Sticker');logJ(j,'Sticker printed');save();};});}
function stickerHtml(kind,km,nk,next){const G=kind==='gear';return `<div class="wstk"><div class="wh">${DB.ws.logo?`<img src="${DB.ws.logo}" alt="">`:''}<b>${esc(DB.ws.name)}</b></div><div class="wbar">${G?'GEARBOX OIL · زيت الجير':'NEXT SERVICE · الصيانة القادمة'}</div><div class="wtwo"><div><small>DATE · التاريخ</small><b>${fmtD(next)}</b></div><em>أو</em><div><small>KM · الكيلومتر</small><b>${nk?kmf(nk):'—'}</b></div></div><div class="wft"><span>${fmtD(now())}${km?' · '+kmf(km)+' km':''}</span><span>${esc(DB.ws.phone||'')}</span></div></div>`;}

/* ---------- CUSTOMERS ---------- */
function custRow(c){const vs=DB.vehicles.filter(v=>v.cust===c.id);const due=DB.jobs.filter(j=>j.cust===c.id&&isInvoiced(j)).reduce((a,j)=>a+jobTotals(j).due,0);
  return `<button class="row" data-go="custd:${c.id}"><div><b>${esc(c.name)}</b><span>${esc(c.phone||'no phone')} · ${vs.map(v=>esc(carName(v))).join(', ')||'no car'}</span></div><span class="v">${due>0.0005?`<em style="color:var(--warn)">${f3(due)}</em>`:'›'}</span></button>`;}
SCREENS.cust=m=>{
  const rd=remindersDue();const q=(S.p.q||'').toLowerCase();
  const list=DB.customers.filter(c=>!q||[c.name,c.phone].some(x=>(x||'').toLowerCase().includes(q))).sort((a,b)=>b.t-a.t);
  m.innerHTML=head('Customers',`<button class="lnk" id="cadd">＋ Add</button>`)+`
  ${sec('Due for a reminder · '+rd.length,'30 days late → next 7 days')}
  ${rd.length?`<div class="list">${rd.map(r=>{const v=byId('vehicles',r.veh)||{},c=byId('customers',r.cust)||{};const d=Math.round((r.due-now())/864e5);return `<div class="card"><div class="h"><b>${esc(c.name||'')}</b><span>${d<0?'due '+(-d)+' days ago':d===0?'due today':'due in '+d+' days'}</span></div><span class="sub">${esc(carName(v))} · ${r.kind==='gear'?'gearbox oil':'engine oil'}${r.dueKm?' · at '+kmf(r.dueKm)+' km':''}</span><div class="two"><button class="btn wa sm" data-rwa="${r.id}">WhatsApp</button><button class="btn ghost sm" data-rs="${r.id}">Mark sent</button></div></div>`;}).join('')}</div>`:empty('🔔','No reminders due. They are made when a job with an oil service is delivered.')}
  ${sec('All customers · '+DB.customers.length)}
  <input class="field" id="cq" placeholder="Search name or phone" value="${esc(S.p.q||'')}">
  ${list.length?`<div class="list">${list.slice(0,80).map(custRow).join('')}</div>`:empty('👥','No customers yet.')}`;
  const cq=$('#cq');cq.oninput=()=>{S.p.q=cq.value;const pos=cq.value.length;render();const e=$('#cq');e.focus();try{e.setSelectionRange(pos,pos);}catch(x){}};
  $$('[data-rs]').forEach(b=>b.onclick=()=>{const r=DB.reminders.find(x=>x.id===b.dataset.rs);r.sent=now();save();render();});
  $$('[data-rwa]').forEach(b=>b.onclick=()=>{const r=DB.reminders.find(x=>x.id===b.dataset.rwa);const v=byId('vehicles',r.veh)||{},c=byId('customers',r.cust)||{};
    const t=msg('remind',{name:c.name||'',car:carName(v),plate:v.plate||'',service:r.kind==='gear'?'تغيير زيت الجير':'تغيير زيت المحرك'});shareText(c.phone,t);r.sent=now();save();});
  $('#cadd').onclick=()=>custSheet();
};
function custSheet(c){const isNew=!c;c=c||{};openSheet(`<h3>${isNew?'New customer':'Edit customer'}</h3><input class="field" id="cn" placeholder="Name" value="${esc(c.name||'')}"><input class="field" id="cp" inputmode="tel" placeholder="Phone" value="${esc(c.phone||'')}"><textarea class="field" id="cnt" rows="2" placeholder="Notes">${esc(c.notes||'')}</textarea><button class="btn" id="cok">Save</button>`,el=>el.querySelector('#cok').onclick=()=>{const n=$('#cn').value.trim();if(!n){toast('Type a name');return;}
  if(isNew){c={id:uid('c'),t:now()};DB.customers.push(c);}c.name=n;c.phone=$('#cp').value.replace(/[^\d+]/g,'');c.notes=$('#cnt').value;save();closeSheet();isNew?go('custd',{id:c.id}):render();});}
function vehSheet(cust,v,dr){const isNew=!v;v=v||{};const d=dr||v;openSheet(`<h3>${isNew?'Add car':'Edit car'}</h3><button class="carpick" id="vcp"></button><input type="hidden" id="vm" value="${esc(d.make||'')}"><input type="hidden" id="vmo" value="${esc(d.model||'')}"><input type="hidden" id="vy" value="${esc(d.year||'')}"><input type="hidden" id="veng" value="${esc(d.engine||'')}"><div class="in2"><input class="field" id="vp" placeholder="Plate" value="${esc(d.plate||'')}" style="text-transform:uppercase"><input class="field" id="vk" inputmode="numeric" placeholder="Km" value="${d.km||''}"></div><select class="field" id="vsz"><option value="">Car size: guess from model</option>${DB.sizes.map((z,k)=>`<option value="${k}" ${d.size===k?'selected':''}>Car size: ${esc(z)}</option>`).join('')}</select><input class="field" id="vv" placeholder="VIN" maxlength="17" value="${esc(d.vin||'')}" style="text-transform:uppercase"><button class="btn" id="vok">Save</button>`,el=>{const cp=el.querySelector('#vcp');const lab=()=>{cp.innerHTML=d.make?`<b>${esc([d.make,d.model,d.year].filter(Boolean).join(' '))}</b><span>${d.engine?esc(d.engine):'Tap to choose the engine'}</span><em>›</em>`:'<b>🚗 Choose make, model, year, engine</b><span>Type “toy” for Toyota…</span><em>›</em>';};lab();
  cp.onclick=()=>{const g=id=>{const e=el.querySelector(id);return e?e.value:'';};const dd=Object.assign({},d,{plate:g('#vp'),km:num(g('#vk')),vin:g('#vv'),size:g('#vsz')===''?null:+g('#vsz')});carPicker(dd,r=>vehSheet(cust,isNew?null:v,Object.assign(dd,r)));};
  el.querySelector('#vok').onclick=()=>{
  if(isNew){v={id:uid('v'),cust:cust.id,t:now()};DB.vehicles.push(v);}v.make=$('#vm').value.trim();v.model=$('#vmo').value.trim();v.year=$('#vy').value.trim();v.engine=$('#veng').value.trim();v.plate=$('#vp').value.trim().toUpperCase();v.km=num($('#vk').value);v.vin=$('#vv').value.trim().toUpperCase();const z=$('#vsz').value;v.size=z===''?null:+z;save();closeSheet();render();};});}
SCREENS.custd=m=>{
  const c=byId('customers',S.p.id);if(!c){go('cust');return;}const vs=DB.vehicles.filter(v=>v.cust===c.id);const js=DB.jobs.filter(j=>j.cust===c.id).sort((a,b)=>b.t-a.t);
  const spent=js.filter(isInvoiced).reduce((a,j)=>a+jobTotals(j).total,0),due=js.filter(isInvoiced).reduce((a,j)=>a+jobTotals(j).due,0);
  m.innerHTML=head(esc(c.name),`<button class="lnk" id="cedit">Edit</button>`)+`
  <div class="card"><span class="sub">${esc(c.phone||'no phone')}${c.notes?' · '+esc(c.notes):''}</span>${c.phone?`<div class="two"><button class="btn wa sm" id="cwa">WhatsApp</button><a class="btn ghost sm" href="tel:${esc(c.phone)}">Call</a></div>`:''}</div>
  <div class="kpis3">${can.money()?`<div class="kpi"><b>${f3(spent)}</b><span>Spent</span></div><div class="kpi ${due>0?'org':''}"><b>${f3(due)}</b><span>Due</span></div>`:''}<div class="kpi"><b>${js.length}</b><span>Visits</span></div></div>
  ${sec('Cars · '+vs.length,`<button class="lnk" id="vadd">＋ Add car</button>`)}
  <div class="list">${vs.map(v=>`<button class="row" data-ve="${v.id}"><div><b>${esc(carName(v))} ${v.plate?`<span class="pl">${esc(v.plate)}</span>`:''}</b><span>${v.km?kmf(v.km)+' km':''}${v.vin?' · '+esc(v.vin):''}</span></div><span class="v">Edit</span></button>`).join('')||empty('🚗','No cars yet.')}</div>
  ${sec('History · '+js.length)}<div class="list">${js.map(carRow).join('')||empty('🧾','No visits yet.')}</div>
  ${can.del()&&!js.length?`<button class="btn ghost jb-del" id="cdel">Delete customer</button>`:''}`;
  $('#cedit').onclick=()=>custSheet(c);$('#vadd').onclick=()=>vehSheet(c);
  $$('[data-ve]').forEach(b=>b.onclick=()=>vehSheet(c,byId('vehicles',b.dataset.ve)));
  const w=$('#cwa');if(w)w.onclick=()=>shareText(c.phone,msg('hello',{name:c.name||''}));
  const d=$('#cdel');if(d)d.onclick=()=>confirmSheet('Delete '+esc(c.name)+'?','Delete',()=>{DB.customers=DB.customers.filter(x=>x!==c);DB.vehicles=DB.vehicles.filter(v=>v.cust!==c.id);save();go('cust');});
};
/* ---------- STOCK ---------- */
/* daily count */
function countToday(){const done=new Set(DB.counts.filter(c=>c.date===today()).map(c=>c.part));const last={};DB.counts.forEach(c=>last[c.part]=Math.max(last[c.part]||0,c.t));
  const pick=DB.parts.slice().sort((a,b)=>(last[a.id]||0)-(last[b.id]||0)).slice(0,5);return pick.filter(p=>!done.has(p.id)).concat(DB.parts.filter(p=>done.has(p.id)));}
SCREENS.count=m=>{const list=countToday().slice(0,Math.max(5,DB.counts.filter(c=>c.date===today()).length));const done=DB.counts.filter(c=>c.date===today());
  m.innerHTML=head('Daily count',`${done.length}/${list.length}`)+`<p class="hint">Count the shelf first, then type the number. The system number shows after you save, so the count stays honest.</p>
  ${list.length?`<div class="list">${list.map(p=>{const c=done.find(x=>x.part===p.id);return `<div class="card cnt${c?' done':''}${c&&Math.abs(c.counted-c.sys)>0.0005?' diff':''}"><b>${esc(p.name)}</b><span class="sub">${sx('loc')&&p.loc?'📍 '+esc(p.loc)+' · ':''}${esc(p.num||p.cat)}</span>${c?`<span class="sub">Counted <b>${c.counted}</b> · system ${c.sys}${Math.abs(c.counted-c.sys)>0.0005?` · <b style="color:var(--bad)">difference ${(c.counted-c.sys).toFixed(2).replace(/\.00$/,'')}</b>`:' ✓'}</span>${Math.abs(c.counted-c.sys)>0.0005&&!c.adj&&can.del()?`<button class="btn ghost sm" data-adj="${c.id}">Set stock to ${c.counted}</button>`:c.adj?'<span class="sub" style="color:var(--ok)">Stock fixed</span>':''}`:`<div class="row2"><input class="field" inputmode="decimal" placeholder="How many on the shelf?" id="cn_${p.id}"><button class="btn okb" data-cs="${p.id}">Save</button></div>`}</div>`;}).join('')}</div>`:empty('📦','Add parts first, then the app picks 5 to count every day.')}`;
  $$('[data-cs]').forEach(b=>b.onclick=()=>{const p=byId('parts',b.dataset.cs);const v=$('#cn_'+p.id).value.trim();if(v==='')return;DB.counts.push({id:uid('k'),date:today(),t:now(),part:p.id,sys:+p.stock||0,counted:num(v),by:S.user.name});save();render();});
  $$('[data-adj]').forEach(b=>b.onclick=()=>{const c=DB.counts.find(x=>x.id===b.dataset.adj);const p=byId('parts',c.part);if(p)mv(p,c.counted-(+p.stock||0),'Count by '+c.by);c.adj=now();save();render();});};
/* suppliers + orders */
SCREENS.vendors=m=>{const pos=DB.pos.slice().sort((a,b)=>b.t-a.t);
  m.innerHTML=head('Suppliers',`<button class="lnk" id="vadd">＋ Supplier</button>`)+`
  <div class="list">${DB.vendors.map(v=>`<button class="row" data-ve="${v.id}"><div><b>${esc(v.name)}</b><span>${esc(v.phone||'')}${v.rep?' · '+esc(v.rep):''}${v.what?' · '+esc(v.what):''}</span></div><span class="v">Edit</span></button>`).join('')||empty('🚚','No suppliers yet.')}</div>
  ${sec('Orders · '+pos.length,DB.vendors.length?'<button class="lnk" id="poadd">＋ New order</button>':'')}
  <div class="list">${pos.map(p=>{const v=byId('vendors',p.vendor)||{};return `<button class="row" data-go="po:${p.id}"><div><b>#${p.no} · ${esc(v.name||'')}</b><span>${p.items.length} items · ${fmtD(p.t)}</span></div><span class="v">${p.status==='received'?'<span class="tag t-ok">Received</span>':p.status==='partial'?'<span class="tag t-warn">Part received</span>':'<span class="tag t-warn">Open</span>'}</span></button>`;}).join('')||empty('📄','No orders yet.')}</div>`;
  $('#vadd').onclick=()=>vendorSheet();$$('[data-ve]').forEach(b=>b.onclick=()=>vendorSheet(byId('vendors',b.dataset.ve)));
  const pa=$('#poadd');if(pa)pa.onclick=()=>{const p=newPo(DB.vendors[0].id);go('po',{id:p.id});};};
function vendorSheet(v){const isNew=!v;v=v||{};openSheet(`<h3>${isNew?'New supplier':'Edit supplier'}</h3><input class="field" id="vn" placeholder="Name" value="${esc(v.name||'')}"><div class="in2"><input class="field" id="vph" inputmode="tel" placeholder="Phone" value="${esc(v.phone||'')}"><input class="field" id="vr" placeholder="Sales rep" value="${esc(v.rep||'')}"></div><input class="field" id="vw" placeholder="What they supply (oils, filters…)" value="${esc(v.what||'')}"><div class="in2"><input class="field" id="vd" placeholder="Delivery (e.g. next day)" value="${esc(v.del||'')}"><input class="field" id="vpay" placeholder="Pay (cash / 30 days)" value="${esc(v.pay||'')}"></div><button class="btn" id="vok">Save</button>`,el=>el.querySelector('#vok').onclick=()=>{const n=$('#vn').value.trim();if(!n){toast('Type a name');return;}if(isNew){v={id:uid('d'),t:now()};DB.vendors.push(v);}Object.assign(v,{name:n,phone:$('#vph').value.trim(),rep:$('#vr').value.trim(),what:$('#vw').value.trim(),del:$('#vd').value.trim(),pay:$('#vpay').value.trim()});save();closeSheet();render();});}
function newPo(vendor,items){const p={id:uid('o'),no:(DB.pos.length?Math.max(...DB.pos.map(x=>x.no)):0)+1,vendor,items:items||[],status:'open',t:now(),by:S.user.name};DB.pos.push(p);save();return p;}
function newPoFromLow(){if(!DB.vendors.length){toast('Add a supplier first');go('vendors');return;}const it=lowParts().map(p=>({part:p.id,q:Math.max(1,Math.round(((+p.reorder||0)*2-(+p.stock||0)))),cost:+p.cost||0}));const p=newPo(DB.vendors[0].id,it);go('po',{id:p.id});}
SCREENS.po=m=>{const p=byId('pos',S.p.id);if(!p){go('vendors');return;}const v=byId('vendors',p.vendor)||{};const tot=p.items.reduce((a,i)=>a+i.q*(i.cost||0),0);const rec=p.status==='received',part=p.status==='partial';
  m.innerHTML=head('Order #'+p.no,rec?'<span class="tag t-ok">Received</span>':part?'<span class="tag t-warn">Part received</span>':'<span class="tag t-warn">Open</span>')+`
  <label class="field-l">Supplier<select class="field" id="pov" ${rec?'disabled':''}>${DB.vendors.map(x=>`<option value="${x.id}" ${x.id===p.vendor?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>
  <div class="list">${p.items.map((i,k)=>{const pt=byId('parts',i.part)||{name:'(deleted part)'};return `<div class="oi"><div><b>${esc(pt.name)}</b><span>stock ${+pt.stock||0}${i.rec?' · got '+i.rec:''}${can.cost()?' · cost '+f3(i.cost||0):''}${(()=>{if(!sx('vprices')||!can.cost())return '';const bv=bestVendor(pt);return bv&&bv.v!==p.vendor&&bv.cost<(+i.cost||Infinity)-0.0005?` · <b style="color:var(--ok)">cheaper: ${esc(byId('vendors',bv.v).name)} ${f3(bv.cost)}</b>`:'';})()}</span></div>${rec?`<em>${i.q}</em>`:`<div class="st"><button data-q="${k}|-1">−</button><input class="qin" data-qi="${k}" inputmode="decimal" value="${i.q}"><button data-q="${k}|1">+</button></div>`}</div>`;}).join('')||empty('📄','No items. Add parts below.')}</div>
  ${rec?'':`<select class="field" id="poadd"><option value="">＋ Add a part…</option><option value="__new">✏️ New part (not in the list yet)…</option>${DB.parts.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select>`}
  ${can.cost()?`<div class="card"><div class="h"><b>Total (cost)</b><b>${f3(tot)} ${DB.ws.currency}</b></div></div>`:''}
  <div class="two"><button class="btn ghost" id="pomsg">📤 Send to supplier</button>${rec?'<span></span>':`<button class="btn okb" id="porec">✓ Received</button>`}</div>
  ${!rec?`<p class="hint">“Received” adds the quantities to stock${can.cost()?' and updates the cost':''}.</p>`:''}
  ${!rec&&can.del()?'<button class="btn ghost jb-del" id="podel">Delete order</button>':''}`;
  $$('[data-qi]').forEach(b=>{b.onfocus=()=>b.select();b.onchange=()=>{const i=p.items[+b.dataset.qi];const q=num(b.value);if(q<=0){p.items.splice(+b.dataset.qi,1);}else i.q=q;save();render();};b.onkeydown=e=>{if(e.key==='Enter')b.blur();};});
  const sv=$('#pov');if(sv)sv.onchange=()=>{p.vendor=sv.value;save();render();};
  $$('[data-q]').forEach(b=>b.onclick=()=>{const [k,d]=b.dataset.q.split('|');const i=p.items[+k];i.q=Math.max(0,i.q+(+d));if(!i.q)p.items.splice(+k,1);save();render();});
  const pa=$('#poadd');if(pa)pa.onchange=()=>{if(!pa.value)return;if(pa.value==='__new'){pa.value='';partSheet(null,pt=>{p.items.push({part:pt.id,q:1,cost:+pt.cost||0});save();render();toast('Part added to stock and to this order');});return;}const pt=byId('parts',pa.value);p.items.push({part:pt.id,q:1,cost:+(((pt.vprices||{})[p.vendor]||{}).cost||pt.cost||0)});save();render();};
  $('#pomsg').onclick=()=>shareText(v.phone,msg('po',{supplier:v.name||'',no:p.no,items:p.items.map(i=>{const pt=byId('parts',i.part)||{};return '• '+(pt.name||'')+(pt.num?' ('+pt.num+')':'')+' × '+i.q+(pt.unit&&pt.unit!=='pc'?' '+pt.unit:'');}).join('\n')}));
  const rc=$('#porec');if(rc)rc.onclick=()=>receivePo(p);
  const dl=$('#podel');if(dl)dl.onclick=()=>{DB.pos=DB.pos.filter(x=>x!==p);save();go('vendors');};};
/* ---------- SERVICES ---------- */
SCREENS.svc=m=>{const q=(S.p.q||'').toLowerCase(),fc=S.p.g||'';const own=perm('svcEdit');
  const vis=g=>DB.services.filter(s=>s.cat===g.name&&!s.hidden&&(!q||(s.name+' '+(s.ar||'')).toLowerCase().includes(q)));const hid=DB.services.filter(s=>s.hidden);
  const tags=s=>[s.from?'<span class="tg tgr">FROM</span>':'',s.out&&s.out.who?'<span class="tg tb">OUTSIDE</span>':'',s.lockP?'<span class="tg tgr">🔒</span>':''].join('');
  const sub=s=>[s.ar?'<bdi>'+esc(s.ar)+'</bdi>':'',s.min?'⏱ '+s.min+' min':'',s.out&&s.out.who?'at '+esc(s.out.who)+' · '+({pass:'not in our sales',share:'we keep '+f3(s.out.amt),pay:'we pay '+f3(s.out.amt)})[s.out.mode]:'',(s.parts||[]).length?'+ '+s.parts.length+' parts':'',s.tag?(s.tag==='oil'?'oil reminder':'gearbox reminder'):'',s.war?'warranty '+esc(s.war):''].filter(Boolean).join(' · ');
  const row=s=>`<button class="row" data-se="${s.id}"><div><b>${esc(s.name)}${tags(s)}</b>${sub(s)?`<span>${sub(s)}</span>`:''}</div><span class="v">${f3(s.p[sizeOf(null)]??s.p[0])}<small>${DB.sizes.length>1?DB.sizes.map((z,k)=>f3(s.p[k]??s.p[s.p.length-1])).filter((x,i,a)=>a.indexOf(x)===i).length>1?'by size':'all sizes':''}</small></span></button>`;
  m.innerHTML=head('Services',own?`<button class="lnk" id="sadd">＋ Service</button>`:'')+`
  ${!DB.ws.svcReviewed&&own?`<div class="card note"><b>These are starter services.</b><span class="sub">Check the prices, delete what you won't do, add your own, and change the groups as you like. Then tap “Prices checked”.</span><button class="btn okb sm" id="srev">Prices checked ✓</button></div>`:''}
  <input class="field" id="sq" placeholder="Search services" value="${esc(S.p.q||'')}">
  <div class="chips"><button data-g="" aria-pressed="${!fc}">All ${DB.services.length-hid.length}</button>${DB.scats.map(g=>`<button data-g="${g.id}" aria-pressed="${fc===g.id}">${g.ic} ${esc(g.name)} ${DB.services.filter(s=>s.cat===g.name&&!s.hidden).length}</button>`).join('')}${own?'<button data-go="list:scat">⚙️ Groups</button><button data-go="list:size">🚙 Car sizes</button>':''}</div>
  ${DB.scats.filter(g=>!fc||g.id===fc).map(g=>{const l=vis(g);if(!l.length&&(q||!own))return '';return sec(`${g.ic} ${esc(g.name)}`,l.length?sizeOf(null)!=null?DB.sizes[sizeOf(null)]+' price':'':'')+`<div class="list">${l.map(row).join('')}${own&&!q?`<button class="row addr" data-sa="${g.id}"><div><b>＋ Add to ${esc(g.name)}</b></div></button>`:''}</div>`;}).join('')}
  ${hid.length&&own&&!fc?sec('🙈 Hidden · '+hid.length,'not shown when adding to a job')+`<div class="list">${hid.map(row).join('')}</div>`:''}`;
  const sq=$('#sq');sq.oninput=()=>{S.p.q=sq.value;const pos=sq.value.length;render();const e=$('#sq');e.focus();try{e.setSelectionRange(pos,pos);}catch(x){}};
  $$('[data-g]').forEach(b=>b.onclick=()=>{S.p.g=b.dataset.g;render();});
  const rv=$('#srev');if(rv)rv.onclick=()=>{DB.ws.svcReviewed=true;save();render();};
  const sa=$('#sadd');if(sa)sa.onclick=()=>svcSheet(null,(DB.scats.find(g=>g.id===fc)||DB.scats[0]||{}).name);
  $$('[data-sa]').forEach(b=>b.onclick=()=>svcSheet(null,DB.scats.find(g=>g.id===b.dataset.sa).name));
  $$('[data-se]').forEach(b=>b.onclick=()=>{if(!own){toast('Not allowed for '+S.user.name);return;}svcSheet(byId('services',b.dataset.se));});};
function svcSheet(s0,cat){const isNew=!s0;const s=JSON.parse(JSON.stringify(s0||{cat:cat||(DB.scats[0]||{}).name||'Other',p:[0],tag:''}));
  s.out=s.out||{who:'',mode:'pass',amt:0};s.parts=s.parts||[];let outOn=!!s.out.who;
  const partners=(DB.mlists.find(L=>/partner|workshop/i.test(L.name))||{items:[]}).items.map(i=>i.name);
  const pr=k=>s.p[k]!=null?s.p[k]:s.p[s.p.length-1];
  openSheet(`<h3>${isNew?'New service':'Edit service'}</h3>
  <input class="field" id="sn" placeholder="Name" value="${esc(s.name||'')}">
  <input class="field ar" id="sar" dir="rtl" placeholder="الاسم بالعربي (يطلع في الفاتورة)" value="${esc(s.ar||'')}">
  <select class="field" id="sc">${DB.scats.map(g=>`<option value="${esc(g.name)}" ${g.name===s.cat?'selected':''}>${g.ic} ${esc(g.name)}</option>`).join('')}<option value="__new">＋ New group…</option></select>
  <input class="field" id="scn" placeholder="New group name" hidden>
  <div class="field-l" style="display:flex;justify-content:space-between;align-items:center">Price by car size <button class="lnk" data-go2="list:size" style="min-height:0;padding:0">Edit sizes ›</button></div>
  <div class="szg" style="grid-template-columns:repeat(${Math.min(DB.sizes.length,4)},minmax(0,1fr))">${DB.sizes.map((z,k)=>`<label class="field-l">${esc(z)}<input class="field" data-sp="${k}" inputmode="decimal" value="${f3(pr(k))}"></label>`).join('')}</div>
  <label class="chk"><input type="checkbox" id="sfr" ${s.from?'checked':''}> Price “starts from” (set the real price on the job)</label>
  <div class="in2"><label class="field-l">Time it takes (min)<input class="field" id="smin" inputmode="numeric" value="${s.min||''}" placeholder="e.g. 30"></label><label class="field-l">Warranty<input class="field" id="swar" value="${esc(s.war||'')}" placeholder="e.g. 3 months"></label></div>
  <div class="field-l">Reminder</div><div class="chips">${[['','None'],['oil','Engine oil'],['gear','Gearbox oil']].map(([k,l])=>`<button data-t="${k}" aria-pressed="${(s.tag||'')===k}">${l}</button>`).join('')}</div>
  <div class="field-l">Parts that come with it</div><div class="list" id="spl"></div>
  <select class="field" id="spa"><option value="">＋ Add a part…</option>${DB.parts.map(p=>`<option value="${p.id}">${esc(p.name)} · ${f3(p.price)}</option>`).join('')}</select>
  <div class="obox"><label class="chk" style="min-height:0"><input type="checkbox" id="soo" ${outOn?'checked':''}> <b>🏪 Done at another workshop</b></label><div id="sob"></div></div>
  ${can.cost()?`<label class="field-l">Worker commission each time (${DB.ws.currency})<input class="field" id="scm" inputmode="decimal" value="${s.comm?f3(s.comm):''}" placeholder="0.000"></label>`:''}
  <label class="chk"><input type="checkbox" id="slk" ${s.lockP?'checked':''}> Workers can't change the price</label>
  <label class="chk"><input type="checkbox" id="shd" ${s.hidden?'checked':''}> Hide (not shown when adding to a job)</label>
  <button class="btn" id="sok">Save</button>${!isNew?'<button class="btn ghost jb-del" id="sdel">Delete service</button>':''}`,el=>{
  let tag=s.tag||'';el.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{tag=b.dataset.t;el.querySelectorAll('[data-t]').forEach(x=>x.setAttribute('aria-pressed',x===b));});
  const sc=el.querySelector('#sc'),scn=el.querySelector('#scn');sc.onchange=()=>{scn.hidden=sc.value!=='__new';if(!scn.hidden)scn.focus();};
  el.querySelectorAll('[data-go2]').forEach(b=>b.onclick=()=>{closeSheet();go('list',{id:'size'});});
  const drawP=()=>{el.querySelector('#spl').innerHTML=s.parts.map((x,k)=>{const p=byId('parts',x.ref)||{name:'(deleted part)'};return `<div class="oi"><div><b>${esc(p.name)}</b><span>${p.unit==='L'?'litres':'qty'}</span></div><div class="st"><button data-pq="${k}|-1">−</button><em>${x.q}</em><button data-pq="${k}|1">+</button></div></div>`;}).join('')||'<p class="hint">None. Example: oil change → oil + filter.</p>';
    el.querySelectorAll('[data-pq]').forEach(b=>b.onclick=()=>{const [k,d]=b.dataset.pq.split('|');const x=s.parts[+k];const p=byId('parts',x.ref)||{};const st=p.unit==='L'?0.5:1;x.q=Math.round((x.q+st*(+d))*10)/10;if(x.q<=0)s.parts.splice(+k,1);drawP();});};
  el.querySelector('#spa').onchange=e=>{const p=byId('parts',e.target.value);if(p)s.parts.push({ref:p.id,q:p.unit==='L'?4:1});e.target.value='';drawP();};drawP();
  const drawO=()=>{const b=el.querySelector('#sob');if(!outOn){b.innerHTML='<p class="hint" style="margin-top:6px">For work you send out, like car wash or tyre repair.</p>';return;}
    b.innerHTML=`<input class="field" id="sow" placeholder="Which workshop" value="${esc(s.out.who)}" list="sowl" style="margin-top:8px"><datalist id="sowl">${partners.map(x=>`<option>${esc(x)}</option>`).join('')}</datalist>
    <div class="seg">${[['pass','Not in our sales'],['share','We keep a share'],['pay','We pay them']].map(([k,l])=>`<button data-om="${k}" class="${s.out.mode===k?'on':''}">${l}</button>`).join('')}</div>
    ${s.out.mode!=='pass'?`<label class="field-l">${s.out.mode==='share'?'We keep each time':'We pay them each time'} (${DB.ws.currency})<input class="field" id="soa" inputmode="decimal" value="${s.out.amt?f3(s.out.amt):''}"></label>`:''}
    <p class="hint">${{pass:'The customer pays us and sees it on the invoice. It is not counted in our sales or profit. The app keeps what we owe them.',share:'Counted in sales. Our profit is only the share we keep; the rest is owed to them.',pay:'Counted in sales. What we pay them is the cost, so profit is the difference.'}[s.out.mode]}</p>`;
    b.querySelectorAll('[data-om]').forEach(x=>x.onclick=()=>{keepO();s.out.mode=x.dataset.om;drawO();});};
  const keepO=()=>{const w=el.querySelector('#sow');if(w)s.out.who=w.value.trim();const a=el.querySelector('#soa');if(a)s.out.amt=num(a.value);};
  el.querySelector('#soo').onchange=e=>{keepO();outOn=e.target.checked;drawO();};drawO();
  el.querySelector('#sok').onclick=()=>{const n=$('#sn').value.trim();if(!n){toast('Type a name');return;}keepO();if(outOn&&!s.out.who){toast('Type which workshop does it');return;}let g=sc.value;
    if(g==='__new'){g=scn.value.trim();if(!g){toast('Type the group name');return;}const ex=DB.scats.find(x=>x.name.toLowerCase()===g.toLowerCase());if(ex)g=ex.name;else DB.scats.push({id:uid('g'),name:g,ic:'🔧'});}
    const t=s0||{id:uid('s'),custom:true};if(!s0)DB.services.push(t);
    Object.assign(t,{name:n,ar:$('#sar').value.trim(),cat:g,p:[...el.querySelectorAll('[data-sp]')].map(i=>num(i.value)),from:$('#sfr').checked,min:parseInt($('#smin').value)||0,war:$('#swar').value.trim(),tag,parts:s.parts,out:outOn?s.out:null,lockP:$('#slk').checked,hidden:$('#shd').checked});
    const cm=$('#scm');if(cm)t.comm=num(cm.value);
    if(outOn&&!partners.includes(s.out.who)){let L=DB.mlists.find(L=>/partner|workshop/i.test(L.name));if(!L){L={id:uid('ml'),name:'Partner workshops',ic:'🏪',note:'Workshops that do work for us.',items:[],inMenu:true};DB.mlists.push(L);}L.items.push({id:uid('li'),name:s.out.who,note:''});}
    save();closeSheet();render();};
  const d=el.querySelector('#sdel');if(d)d.onclick=()=>confirmSheet(`Delete “${esc(s0.name)}”? Old invoices keep it.`,'Delete service',()=>{DB.services=DB.services.filter(x=>x!==s0);save();render();});});}
/* canned jobs */
SCREENS.canned=m=>{m.innerHTML=head('Canned jobs',`<button class="lnk" id="cjadd">＋ New</button>`)+`<p class="hint">A canned job is a set you add in one tap, e.g. “Camry 2.5 oil service” = oil 4.4 L + filter + labour.</p>
  <div class="list">${DB.canned.map(c=>`<button class="row" data-cj="${c.id}"><div><b>${esc(c.name)}</b><span>${c.items.map(i=>esc(i.d)).join(' + ')}</span></div><span class="v">${f3(c.items.reduce((a,i)=>a+i.q*i.p,0))}</span></button>`).join('')||empty('📦','No canned jobs yet.')}</div>`;
  $('#cjadd').onclick=()=>cannedSheet();$$('[data-cj]').forEach(b=>b.onclick=()=>cannedSheet(DB.canned.find(x=>x.id===b.dataset.cj)));};
function cannedSheet(c){const isNew=!c;c=c||{name:'',items:[]};const items=c.items.map(i=>Object.assign({},i));
  const draw=el=>{el.querySelector('#cji').innerHTML=items.map((i,k)=>`<div class="oi"><div><b>${esc(i.d)}</b><span>${i.k==='part'?'Part':'Labour'} · ${f3(i.p)}${i.u?'/'+i.u:''}</span></div><div class="st"><button data-cq="${k}|-1">−</button><em>${i.q}</em><button data-cq="${k}|1">+</button></div></div>`).join('')+`<div class="card"><div class="h"><b>Total</b><b>${f3(items.reduce((a,i)=>a+i.q*i.p,0))}</b></div></div>`;
    el.querySelectorAll('[data-cq]').forEach(b=>b.onclick=()=>{const [k,d]=b.dataset.cq.split('|');const i=items[+k];const st=i.u==='L'?0.1:1;i.q=Math.round((i.q+st*(+d))*10)/10;if(i.q<=0)items.splice(+k,1);draw(el);});};
  openSheet(`<h3>${isNew?'New canned job':'Edit canned job'}</h3><input class="field" id="cjn" placeholder="Name (e.g. Camry 2.5 oil service)" value="${esc(c.name)}"><div id="cji" class="list"></div>
   <select class="field" id="cjs"><option value="">＋ Add a service…</option>${DB.services.map(s=>`<option value="${s.id}">${esc(s.name)} · ${f3(s.p[0])}</option>`).join('')}</select>
   <select class="field" id="cjp"><option value="">＋ Add a part…</option>${DB.parts.map(p=>`<option value="${p.id}">${esc(p.name)} · ${f3(p.price)}</option>`).join('')}</select>
   <button class="btn" id="cjok">Save</button>${!isNew?'<button class="btn ghost jb-del" id="cjdel">Delete</button>':''}`,el=>{draw(el);
   el.querySelector('#cjs').onchange=e=>{const s=byId('services',e.target.value);if(s)items.push({k:'labour',ref:s.id,d:s.name,q:1,u:'',p:s.p[0],tag:s.tag});e.target.value='';draw(el);};
   el.querySelector('#cjp').onchange=e=>{const p=byId('parts',e.target.value);if(p)items.push({k:'part',ref:p.id,d:p.name,num:p.num,q:p.unit==='L'?4:1,u:p.unit==='L'?'L':'',p:+p.price,cost:+p.cost||0});e.target.value='';draw(el);};
   el.querySelector('#cjok').onclick=()=>{const n=$('#cjn').value.trim();if(!n||!items.length){toast('Name and at least one item');return;}if(isNew){c.id=uid('t');DB.canned.push(c);}c.name=n;c.items=items;save();closeSheet();render();};
   const d=el.querySelector('#cjdel');if(d)d.onclick=()=>{DB.canned=DB.canned.filter(x=>x!==c);save();closeSheet();render();};});}
/* inspections */
SCREENS.insp=m=>{m.innerHTML=head('Inspection checklists',`<button class="lnk" id="iadd">＋ New</button>`)+`<p class="hint">Keep them short: 15 to 20 items. Workers tap green, yellow or red.</p><div class="list">${DB.insp.map(t=>`<button class="row" data-ie="${t.id}"><div><b>${esc(t.name)}</b><span>${t.items.length} items</span></div><span class="v">Edit</span></button>`).join('')}</div>`;
  const edit=t=>{const isNew=!t;t=t||{name:'',items:[]};openSheet(`<h3>${isNew?'New checklist':'Edit checklist'}</h3><input class="field" id="in" placeholder="Name" value="${esc(t.name)}"><label class="field-l">One item per line<textarea class="field" id="ii" rows="10">${esc(t.items.join('\n'))}</textarea></label><button class="btn" id="iok">Save</button>${!isNew?'<button class="btn ghost jb-del" id="idel">Delete</button>':''}`,el=>{
   el.querySelector('#iok').onclick=()=>{const n=$('#in').value.trim();const it=$('#ii').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!n||!it.length){toast('Name and items');return;}if(isNew){t.id=uid('i');DB.insp.push(t);}t.name=n;t.items=it;save();closeSheet();render();};
   const d=el.querySelector('#idel');if(d)d.onclick=()=>{DB.insp=DB.insp.filter(x=>x!==t);save();closeSheet();render();};});};
  $('#iadd').onclick=()=>edit();$$('[data-ie]').forEach(b=>b.onclick=()=>edit(DB.insp.find(x=>x.id===b.dataset.ie)));};

/* ---------- STOCK (10 extra tools, each can be turned off in Stock tools) ---------- */
const SX=[['smart','✨','Smart services','Oil change, plugs, pads, battery: compare options side by side and add the right parts'],
 ['moves','📜','Part history','Every in and out for each part: invoice, return, supplier, count'],
 ['scan','📷','Barcode scan','Scan with the camera in stock, jobs and the part form'],
 ['markup','💹','Price from cost','Profit % per category; suggests the selling price'],
 ['vprices','🚚','Prices per supplier','Remembers each supplier\'s price; shows the cheapest'],
 ['alts','🔁','Alternative parts','Suggests an alternative when a part is out of stock'],
 ['fits','🚗','Fits these cars','Parts that fit the car show first on the job'],
 ['slow','🐢','Slow parts','Parts not sold for 60 or 90 days and the money in them'],
 ['value','💰','Stock value','Value at cost and at selling price, by category'],
 ['partial','📦','Part receiving','Receive part of an order; the rest stays open'],
 ['loc','📍','Shelf place','Where the part is kept (shelf A3, drawer 2)']];
const sx=k=>!((DB.ws&&DB.ws.sxOff)||{})[k];
const r2=x=>Math.round(x*100)/100;
function mv(p,q,why,ref){if(!p||!q)return;p.stock=r2((+p.stock||0)+q);(DB.moves=DB.moves||[]).push({t:now(),part:p.id,q:r2(q),why,ref:ref||'',by:S.user?S.user.name:'',bal:p.stock});}
const unitS=p=>p.unit==='L'?'L':p.unit&&p.unit!=='pc'?p.unit:'';
function lastSold(){const o={};DB.jobs.filter(isInvoiced).forEach(j=>(j.items||[]).forEach(i=>{if(i.k==='part'&&i.ref)o[i.ref]=Math.max(o[i.ref]||0,j.inv.t);}));return o;}
function fitsCar(p,v){if(!p.fits||!v)return false;const car=((v.make||'')+' '+(v.model||'')+' '+(v.year||'')+' '+(v.engine||'')).toLowerCase();
  return p.fits.split(/[,،\n]/).map(x=>x.trim().toLowerCase()).filter(Boolean).some(f=>{const w=f.split(/\s+/);const yr=w.find(x=>/^\d{4}(-\d{4})?$/.test(x));const words=w.filter(x=>x!==yr);
    if(!words.every(x=>car.includes(x)))return false;if(!yr||!v.year)return true;const [a,b]=yr.split('-').map(Number);const y=+v.year;return y>=a&&y<=(b||a);});}
const markOf=cat=>+((DB.markup||{})[cat])||0;
const suggestPrice=p=>{const m=markOf(p.cat);return m&&+p.cost?Math.round((+p.cost)*(1+m/100)*10)/10:0;};
function bestVendor(p){const vp=p.vprices||{};let b=null;Object.entries(vp).forEach(([v,x])=>{if(byId('vendors',v)&&(!b||x.cost<b.cost))b={v,cost:x.cost,t:x.t};});return b;}
/* barcode */
async function scanSheet(onCode){if(!('BarcodeDetector' in window)){toast('This phone has no built-in scanner. Type the number, or use a scanner gun.');return;}
  let stream,stop=false;openSheet(`<h3>📷 Scan a barcode</h3><video id="scv" playsinline muted style="width:100%;border-radius:14px;background:#000;max-height:50vh;object-fit:cover"></video><p class="hint">Hold the barcode inside the picture.</p>`,()=>{});
  const end=()=>{stop=true;if(stream)stream.getTracks().forEach(t=>t.stop());};const cb=$('#sheet [data-close]');if(cb)cb.addEventListener('click',end);
  try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const vd=$('#scv');vd.srcObject=stream;await vd.play();
    const det=new BarcodeDetector();const loop=async()=>{if(stop||!$('#scv'))return end();try{const r=await det.detect(vd);if(r.length){const c=r[0].rawValue;end();closeSheet();onCode(c);return;}}catch(e){}requestAnimationFrame(loop);};loop();
  }catch(e){end();closeSheet();toast('Camera not allowed. Allow the camera for this app in phone settings.');}}
function findByCode(c){c=(c||'').trim();return DB.parts.find(p=>p.num&&p.num.trim()===c)||DB.parts.find(p=>(p.codes||[]).includes(c));}
/* stock screen */
SCREENS.stock=m=>{
  const q=(S.p.q||'').toLowerCase(),cat=S.p.cat||'';
  const list=DB.parts.filter(p=>(!cat||p.cat===cat)&&(!q||(p.name+' '+(p.num||'')+' '+(p.loc||'')+' '+(p.fits||'')).toLowerCase().includes(q))).sort((a,b)=>a.name.localeCompare(b.name));
  const low=lowParts();const val=DB.parts.reduce((a,p)=>a+(+p.stock||0)*(+p.cost||0),0);
  m.innerHTML=head('Stock',`<button class="lnk" id="padd">＋ Part</button>`)+`
  <div class="kpis3"><div class="kpi"><b>${DB.parts.length}</b><span>Parts</span></div><button class="kpi ${low.length?'red':''}" id="plow"><b>${low.length}</b><span>To order</span></button>${can.cost()?`<button class="kpi" ${sx('value')?'data-go="stockval"':''}><b>${f3(val)}</b><span>On the shelf (cost)</span></button>`:`<button class="kpi" data-go="count"><b>${countToday().length}</b><span>To count</span></button>`}</div>
  <div class="two"><button class="btn ghost sm" data-go="count">📦 Daily count</button><button class="btn ghost sm" data-go="vendors">🚚 Suppliers & orders</button></div>
  ${(sx('slow')||sx('value')||can.settings())?`<div class="chips">${sx('slow')?'<button data-go="slow">🐢 Slow parts</button>':''}${sx('value')&&can.cost()?'<button data-go="stockval">💰 Stock value</button>':''}${can.settings()?'<button data-go="stocktools">⚙️ Stock tools</button>':''}</div>`:''}
  ${low.length?sec('Order now · '+low.length,`<button class="lnk" id="mkpo">Make an order ›</button>`)+`<div class="list">${low.map(partRow).join('')}</div>`:''}
  ${sec('All parts')}
  <div class="srow"><input class="field" id="pq" placeholder="Search name, number${sx('loc')?', shelf':''}" value="${esc(S.p.q||'')}">${sx('scan')?'<button class="scanb" id="pscan">📷</button>':''}</div>
  <div class="chips">${['',...DB.pcats].map(c=>`<button data-cat="${esc(c)}" aria-pressed="${cat===c}">${c||'All'}</button>`).join('')}</div>
  ${list.length?`<div class="list">${list.map(partRow).join('')}</div>`:empty('🛢',DB.parts.length?'Nothing found.':'No parts yet. Tap <b>＋ Part</b> to add your first one.')}`;
  const pq=$('#pq');pq.oninput=()=>{S.p.q=pq.value;const pos=pq.value.length;render();const e=$('#pq');e.focus();try{e.setSelectionRange(pos,pos);}catch(x){}};
  $$('[data-cat]').forEach(b=>b.onclick=()=>{S.p.cat=b.dataset.cat;render();});
  $('#padd').onclick=()=>partSheet();$$('[data-pe]').forEach(b=>b.onclick=()=>partSheet(byId('parts',b.dataset.pe)));
  const mk=$('#mkpo');if(mk)mk.onclick=()=>newPoFromLow();
  const ps=$('#pscan');if(ps)ps.onclick=()=>scanSheet(c=>{const p=findByCode(c);if(p)partSheet(p);else confirmSheet('No part with '+esc(c)+'. Add it as a new part?','＋ New part',()=>partSheet({cat:DB.pcats[0],unit:'pc',num:c},null,true));});
};
function partRow(p){const lo=(+p.reorder||0)>0&&(+p.stock||0)<=(+p.reorder||0);return `<button class="row" data-pe="${p.id}"><div><b>${esc(p.name)}</b><span>${sx('loc')&&p.loc?'📍 '+esc(p.loc)+' · ':''}${esc(p.num||'')}${p.num?' · ':''}${esc(p.cat)} · ${f3(p.price)}${p.unit==='L'?'/L':''}${lo?' · <span class="tag t-bad">Order</span>':''}</span></div><span class="v ${(+p.stock||0)<=0?'bad':''}">${+p.stock||0}<small>${p.unit==='L'?'L':p.unit||'pc'}</small></span></button>`;}
function partSheet(p,onSaved,forceNew,draft){const isNew=!p||forceNew;p=p||{cat:DB.pcats[0],unit:'pc'};const w=JSON.parse(JSON.stringify(draft||p));w.alts=w.alts||[];w.vprices=w.vprices||{};
  const mvs=(DB.moves||[]).filter(x=>x.part===p.id).sort((a,b)=>b.t-a.t);
  openSheet(`<h3>${isNew?'New part':'Edit part'}</h3><input class="field" id="pn" placeholder="Name · brand type size (e.g. Toyota Oil Filter 90915-YZZN2)" value="${esc(w.name||'')}">
   <div class="in2"><div class="srow"><input class="field" id="pnum" placeholder="Part number / barcode" value="${esc(w.num||'')}">${sx('scan')?'<button class="scanb" id="pnsc">📷</button>':''}</div><select class="field" id="pcat">${DB.pcats.map(c=>`<option ${w.cat===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>
   <div class="chips">${DB.units.map(k=>[k,unitName(k)]).map(([k,l])=>`<button data-u="${k}" aria-pressed="${w.unit===k}">${l}</button>`).join('')}</div>
   <div id="pgr"></div>
   <div class="in2"><label class="field-l">Selling price<input class="field" id="ppr" inputmode="decimal" value="${w.price?f3(w.price):''}"></label>${can.cost()?`<label class="field-l">Cost (owner only)<input class="field" id="pco" inputmode="decimal" value="${w.cost?f3(w.cost):''}"></label>`:'<span></span>'}</div>
   ${sx('markup')&&can.cost()?'<div id="psug"></div>':''}
   <div class="in2"><label class="field-l">In stock<input class="field" id="pst" inputmode="decimal" value="${w.stock||''}" ${isNew||can.del()?'':'disabled'}></label><label class="field-l">Reorder at<input class="field" id="pro" inputmode="decimal" value="${w.reorder||''}"></label></div>
   ${sx('loc')?`<label class="field-l">📍 Shelf place<input class="field" id="ploc" placeholder="e.g. Shelf A3 · Drawer 2" value="${esc(w.loc||'')}"></label>`:''}
   ${sx('fits')?`<label class="field-l">🚗 Fits these cars (comma between)<input class="field" id="pfit" placeholder="e.g. Camry 2012-2017, Corolla, Lexus ES" value="${esc(w.fits||'')}"></label>`:''}
   ${sx('alts')?`<div class="field-l">🔁 Alternative parts</div><div class="list" id="palt"></div><select class="field" id="paltadd"><option value="">＋ Add an alternative…</option>${DB.parts.filter(x=>x.id!==p.id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select>`:''}
   ${sx('vprices')&&can.cost()&&DB.vendors.length?`<div class="field-l">🚚 Price per supplier</div><div class="list" id="pvp"></div><div class="in2"><select class="field" id="pvv">${DB.vendors.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select><div class="row2"><input class="field" id="pvc" inputmode="decimal" placeholder="Their price"><button class="btn ghost sm" id="pvok">＋</button></div></div>`:''}
   ${isNew?'':'<p class="hint">Stock changes by itself with invoices and supplier orders. Change it here only after a count.</p>'}
   <button class="btn" id="pok">Save</button>
   ${sx('moves')&&!isNew?sec('📜 History',mvs.length+' moves')+`<div class="list">${mvs.slice(0,30).map(x=>`<div class="row"><div><b>${esc(x.why)}</b><span>${fmtD(x.t)} ${hm(x.t)}${x.by?' · '+esc(x.by):''}</span></div><span class="v ${x.q<0?'bad':''}" style="${x.q>0?'color:var(--ok)!important':''}">${x.q>0?'+':''}${x.q}<small>left ${x.bal}</small></span></div>`).join('')||'<p class="hint">No moves yet.</p>'}</div>`:''}
   ${!isNew&&can.del()?'<button class="btn ghost jb-del" id="pdel">Delete part</button>':''}`,el=>{
   let unit=w.unit;el.querySelectorAll('[data-u]').forEach(b=>b.onclick=()=>{unit=b.dataset.u;el.querySelectorAll('[data-u]').forEach(x=>x.setAttribute('aria-pressed',x===b));});
   const sc=el.querySelector('#pnsc');if(sc)sc.onclick=()=>{const g=id=>{const e=el.querySelector(id);return e?e.value:undefined;};const d=Object.assign({},w,{name:g('#pn'),cat:g('#pcat'),unit,price:num(g('#ppr')),stock:num(g('#pst')),reorder:num(g('#pro'))});if(g('#pco')!==undefined)d.cost=num(g('#pco'));if(g('#ploc')!==undefined)d.loc=g('#ploc');if(g('#pfit')!==undefined)d.fits=g('#pfit');scanSheet(c=>{d.num=c;partSheet(p,onSaved,isNew,d);});};
   let grade=w.grade||gradeOf(w);const drawG=()=>{const b=el.querySelector('#pgr');if(!b)return;if(!sx('smart')||$('#pcat').value!=='Engine oil'){b.innerHTML='';return;}if(!w.grade&&!grade)grade=gradeOf({name:$('#pn').value});b.innerHTML=`<div class="field-l">Oil type (for the oil change compare)</div><div class="chips">${Object.entries(GRADE).map(([k,[n,km]])=>`<button data-gr="${k}" aria-pressed="${grade===k}">${n} · ${kmf(km)} km</button>`).join('')}</div>`;b.querySelectorAll('[data-gr]').forEach(x=>x.onclick=()=>{grade=x.dataset.gr;drawG();});};drawG();el.querySelector('#pcat').addEventListener('change',drawG);el.querySelector('#pn').addEventListener('change',drawG);
   const sug=el.querySelector('#psug');const drawSug=()=>{if(!sug)return;const cat=$('#pcat').value,co=num($('#pco').value),mk=markOf(cat);if(!mk||!co){sug.innerHTML=mk?'':`<p class="hint">Set a profit % for ${esc(cat)} in Stock tools to get a suggested price.</p>`;return;}const s=Math.round(co*(1+mk/100)*10)/10;sug.innerHTML=`<button class="btn ghost sm" id="psug2">💹 Use ${f3(s)} (cost + ${mk}%)</button>`;el.querySelector('#psug2').onclick=()=>{$('#ppr').value=f3(s);};};
   if(sug){$('#pco').oninput=drawSug;$('#pcat').addEventListener('change',drawSug);drawSug();}
   const drawAlt=()=>{const b=el.querySelector('#palt');if(!b)return;b.innerHTML=w.alts.map(id=>{const x=byId('parts',id);return x?`<div class="row"><div><b>${esc(x.name)}</b><span>stock ${+x.stock||0}</span></div><button class="lnk" data-ax="${id}">✕</button></div>`:'';}).join('')||'<p class="hint">None.</p>';b.querySelectorAll('[data-ax]').forEach(x=>x.onclick=()=>{w.alts=w.alts.filter(i=>i!==x.dataset.ax);drawAlt();});};drawAlt();
   const aa=el.querySelector('#paltadd');if(aa)aa.onchange=()=>{if(aa.value&&!w.alts.includes(aa.value))w.alts.push(aa.value);aa.value='';drawAlt();};
   const drawVp=()=>{const b=el.querySelector('#pvp');if(!b)return;const best=bestVendor(w);b.innerHTML=Object.entries(w.vprices).filter(([v])=>byId('vendors',v)).sort((a,c)=>a[1].cost-c[1].cost).map(([v,x])=>`<div class="row"><div><b>${esc(byId('vendors',v).name)}${best&&best.v===v?' <span class="tg tgr">cheapest</span>':''}</b><span>${fmtD(x.t)}</span></div><span class="v">${f3(x.cost)}</span><button class="lnk" data-vx="${v}">✕</button></div>`).join('')||'<p class="hint">Fills in by itself when you receive orders.</p>';b.querySelectorAll('[data-vx]').forEach(x=>x.onclick=()=>{delete w.vprices[x.dataset.vx];drawVp();});};drawVp();
   const vo=el.querySelector('#pvok');if(vo)vo.onclick=()=>{const c=num($('#pvc').value);if(!c)return;w.vprices[$('#pvv').value]={cost:c,t:now()};$('#pvc').value='';drawVp();};
   el.querySelector('#pok').onclick=()=>{const n=$('#pn').value.trim();if(!n){toast('Type a name');return;}const nm=$('#pnum').value.trim();
     const dup=DB.parts.find(x=>x!==p&&(x.name.toLowerCase()===n.toLowerCase()||(nm&&x.num===nm)));if(dup){toast('This part already exists: '+dup.name);return;}
     let t=p;if(isNew){t={id:uid('p'),t:now(),stock:0};DB.parts.push(t);}
     const ns=num($('#pst').value),os=+t.stock||0;
     Object.assign(t,{grade:$('#pcat').value==='Engine oil'?grade:t.grade,name:n,num:nm,cat:$('#pcat').value,unit,price:num($('#ppr').value),reorder:num($('#pro').value)});const co=$('#pco');if(co)t.cost=num(co.value);
     const g=id=>{const e=el.querySelector(id);return e?e.value.trim():undefined;};if(g('#ploc')!==undefined)t.loc=g('#ploc');if(g('#pfit')!==undefined)t.fits=g('#pfit');
     if(el.querySelector('#palt')){const old=t.alts||[];t.alts=w.alts;old.filter(i=>!w.alts.includes(i)).forEach(i=>{const x=byId('parts',i);if(x)x.alts=(x.alts||[]).filter(y=>y!==t.id);});w.alts.forEach(i=>{const x=byId('parts',i);if(x){x.alts=x.alts||[];if(!x.alts.includes(t.id))x.alts.push(t.id);}});}
     if(el.querySelector('#pvp'))t.vprices=w.vprices;
     if(Math.abs(ns-os)>0.0001)mv(t,ns-os,isNew?'Opening stock':'Changed by hand');
     save();closeSheet();if(onSaved)onSaved(t);else render();};
   const d=el.querySelector('#pdel');if(d)d.onclick=()=>confirmSheet('Delete '+esc(p.name)+'?','Delete part',()=>{DB.parts=DB.parts.filter(x=>x!==p);save();render();});});}
/* add-to-job part list: fits first, alternatives when out */
function partOpts(v,ps){const fit=sx('fits');const L=ps.map(p=>({p,f:fit&&fitsCar(p,v)})).sort((a,b)=>(b.f-a.f));
  return L.slice(0,60).map(({p,f})=>{let alt='';if(sx('alts')&&(+p.stock||0)<=0){const a=(p.alts||[]).map(i=>byId('parts',i)).filter(x=>x&&(+x.stock||0)>0)[0];if(a)alt=`<button class="opt alt" data-pt="${a.id}"><div class="tx"><b>↳ Instead: ${esc(a.name)}</b><span>${+a.stock}${unitS(a)?' '+unitS(a):''} in stock${sx('loc')&&a.loc?' · 📍 '+esc(a.loc):''}</span></div><span class="v">${f3(a.price)}</span></button>`;}
    return `<button class="opt" data-pt="${p.id}"><div class="tx"><b>${esc(p.name)}${f?' <span class="tg tok">fits</span>':''}</b><span>${esc(p.num||p.cat)} · ${+p.stock>0?(+p.stock)+(p.unit==='L'?' L':'')+' in stock':'out of stock'}${sx('loc')&&p.loc?' · 📍 '+esc(p.loc):''}</span></div><span class="v">${f3(p.price)}${p.unit==='L'?'<small>/L</small>':''}</span></button>`+alt;}).join('');}
/* slow parts */
SCREENS.slow=m=>{const d=+S.p.d||60;const ls=lastSold();const cut=now()-d*864e5;
  const L=DB.parts.filter(p=>(+p.stock||0)>0&&(ls[p.id]||p.t||0)<cut).sort((a,b)=>(+b.stock*(+b.cost||0))-(+a.stock*(+a.cost||0)));const tied=L.reduce((a,p)=>a+(+p.stock)*(+p.cost||0),0);
  m.innerHTML=head('🐢 Slow parts')+`<div class="chips">${[30,60,90,180].map(x=>`<button data-d="${x}" aria-pressed="${x===d}">${x} days</button>`).join('')}</div>
  <div class="kpis2"><div class="kpi"><b>${L.length}</b><span>Parts not sold in ${d} days</span></div>${can.cost()?`<div class="kpi org"><b>${f3(tied)}</b><span>Money on the shelf (cost)</span></div>`:''}</div>
  <div class="list">${L.map(p=>`<button class="row" data-pe="${p.id}"><div><b>${esc(p.name)}</b><span>${ls[p.id]?'last sold '+ago(ls[p.id]):'never sold'} · ${+p.stock} ${unitS(p)||'pc'}</span></div><span class="v">${can.cost()?f3((+p.stock)*(+p.cost||0)):''}</span></button>`).join('')||empty('👍','Nothing slow. Everything sold in the last '+d+' days.')}</div>`;
  $$('[data-d]').forEach(b=>b.onclick=()=>{S.p.d=b.dataset.d;render();});$$('[data-pe]').forEach(b=>b.onclick=()=>partSheet(byId('parts',b.dataset.pe)));};
/* stock value */
SCREENS.stockval=m=>{if(!can.cost()){go('stock');return;}const by={};DB.parts.forEach(p=>{const s=Math.max(0,+p.stock||0);const o=by[p.cat]=by[p.cat]||{n:0,c:0,p:0};o.n++;o.c+=s*(+p.cost||0);o.p+=s*(+p.price||0);});
  const T=Object.values(by).reduce((a,o)=>({c:a.c+o.c,p:a.p+o.p}),{c:0,p:0});
  m.innerHTML=head('💰 Stock value')+`<div class="kpis3"><div class="kpi"><b>${f3(T.c)}</b><span>At cost</span></div><div class="kpi ok"><b>${f3(T.p)}</b><span>At selling price</span></div><div class="kpi"><b>${f3(T.p-T.c)}</b><span>Profit inside</span></div></div>
  ${sec('By category')}<div class="list">${Object.entries(by).sort((a,b)=>b[1].c-a[1].c).map(([k,o])=>`<div class="row"><div><b>${esc(k)}</b><span>${o.n} parts · sells for ${f3(o.p)}</span></div><span class="v">${f3(o.c)}<small>cost</small></span></div>`).join('')||empty('🛢','No parts yet.')}</div>`;};
/* settings for the 10 tools */
SCREENS.stocktools=m=>{if(!can.settings()){go('stock');return;}DB.ws.sxOff=DB.ws.sxOff||{};DB.markup=DB.markup||{};
  m.innerHTML=head('⚙️ Stock tools')+`<p class="hint">Turn off what you don't need. Turning off only hides it; nothing is deleted.</p>
  <div class="list">${SX.map(([k,ic,t,d])=>`<label class="lrow tgl2"><span class="lname"><span class="ic">${ic}</span><div><b>${t}</b><span>${d}</span></div></span><input type="checkbox" data-sx="${k}" ${sx(k)?'checked':''}></label>`).join('')}</div>
  ${sx('markup')?sec('💹 Profit % by category','used for the suggested price')+`<div class="list">${DB.pcats.map(c=>`<div class="lrow"><span class="lname"><div><b>${esc(c)}</b></div></span><input class="qin" style="width:84px" data-mu="${esc(c)}" inputmode="decimal" placeholder="%" value="${DB.markup[c]||''}"></div>`).join('')}</div><button class="btn ghost sm" id="muall">Update selling prices of all parts from cost</button>`:''}`;
  $$('[data-sx]').forEach(b=>b.onchange=()=>{if(b.checked)delete DB.ws.sxOff[b.dataset.sx];else DB.ws.sxOff[b.dataset.sx]=1;save();render();});
  $$('[data-mu]').forEach(b=>b.onchange=()=>{const v=num(b.value);if(v)DB.markup[b.dataset.mu]=v;else delete DB.markup[b.dataset.mu];save();});
  const ma=$('#muall');if(ma)ma.onclick=()=>{const L=DB.parts.filter(p=>suggestPrice(p)&&Math.abs(suggestPrice(p)-(+p.price||0))>0.0005);if(!L.length){toast('All prices already match');return;}
    openSheet(`<h3>New prices · ${L.length}</h3><div class="list">${L.map(p=>`<label class="lrow tgl2"><span class="lname"><div><b>${esc(p.name)}</b><span>${f3(p.price||0)} → <b>${f3(suggestPrice(p))}</b></span></div></span><input type="checkbox" data-np="${p.id}" checked></label>`).join('')}</div><button class="btn" id="npok">Apply</button>`,el=>el.querySelector('#npok').onclick=()=>{el.querySelectorAll('[data-np]:checked').forEach(c=>{const p=byId('parts',c.dataset.np);p.price=suggestPrice(p);});save();closeSheet();toast('Prices updated');});};};
/* receive a supplier order (all or part) */
function receivePo(p){const v=byId('vendors',p.vendor)||{};const left=p.items.map(i=>({i,rest:r2(i.q-(+i.rec||0))})).filter(x=>x.rest>0);
  const apply=got=>{const changed=[];got.forEach(([i,q,c])=>{if(!q)return;const pt=byId('parts',i.part);if(!pt)return;mv(pt,q,'Supplier order #'+p.no+(v.name?' · '+v.name:''),p.id);i.rec=r2((+i.rec||0)+q);
      if(c){if(Math.abs(c-(+pt.cost||0))>0.0005)changed.push(pt);pt.cost=c;i.cost=c;}if(c&&p.vendor){pt.vprices=pt.vprices||{};pt.vprices[p.vendor]={cost:c,t:now()};}});
    p.status=p.items.every(i=>(+i.rec||0)>=i.q-0.0001)?'received':'partial';p.rt=now();save();
    const sug=sx('markup')?changed.filter(pt=>suggestPrice(pt)&&Math.abs(suggestPrice(pt)-(+pt.price||0))>0.0005):[];
    if(sug.length&&can.cost()){openSheet(`<h3>Cost changed · new selling prices?</h3><div class="list">${sug.map(pt=>`<label class="lrow tgl2"><span class="lname"><div><b>${esc(pt.name)}</b><span>${f3(pt.price||0)} → <b>${f3(suggestPrice(pt))}</b></span></div></span><input type="checkbox" data-np="${pt.id}" checked></label>`).join('')}</div><button class="btn" id="npok">Apply</button>`,el=>el.querySelector('#npok').onclick=()=>{el.querySelectorAll('[data-np]:checked').forEach(c=>{const x=byId('parts',c.dataset.np);x.price=suggestPrice(x);});save();closeSheet();render();});}
    render();toast(p.status==='received'?'Stock updated':'Received part of the order. The rest stays open.');};
  if(!sx('partial')){confirmSheet('Mark order #'+p.no+' as received? Stock goes up.','Received',()=>apply(left.map(x=>[x.i,x.rest,+x.i.cost||0])));return;}
  openSheet(`<h3>Receive order #${p.no}</h3><p class="hint">Type what arrived. Leave less if some did not come; the rest stays open.</p><div class="list">${left.map((x,k)=>{const pt=byId('parts',x.i.part)||{name:'?'};return `<div class="oi"><div><b>${esc(pt.name)}</b><span>ordered ${x.i.q}${x.i.rec?' · got '+x.i.rec:''}</span></div><div class="st">${can.cost()?`<input class="qin" style="width:76px" data-rc="${k}" inputmode="decimal" placeholder="cost" value="${x.i.cost?f3(x.i.cost):''}">`:''}<input class="qin" data-rq="${k}" inputmode="decimal" value="${x.rest}"></div></div>`;}).join('')}</div><button class="btn okb" id="rcok">✓ Save received</button>`,el=>{
    el.querySelectorAll('.qin').forEach(b=>b.onfocus=()=>b.select());
    el.querySelector('#rcok').onclick=()=>{const got=left.map((x,k)=>{const q=Math.min(x.rest,num(el.querySelector(`[data-rq="${k}"]`).value));const ce=el.querySelector(`[data-rc="${k}"]`);return [x.i,q,ce?num(ce.value):(+x.i.cost||0)];});closeSheet();apply(got);};});}

/* ---------- MONEY ---------- */
function rangeOf(k){const d=new Date();const s=new Date(d.toLocaleString('en-US',{timeZone:'Asia/Muscat'}));s.setHours(0,0,0,0);
  if(k==='week')s.setDate(s.getDate()-6);if(k==='month')s.setDate(1);if(k==='year')s.setMonth(0,1);return s.getTime()-(new Date().getTimezoneOffset()+240)*60e3*0;}
function sumRange(from){const inv=DB.jobs.filter(j=>isInvoiced(j)&&j.inv.t>=from);const T=inv.map(jobTotals);
  const pays=DB.jobs.flatMap(j=>(j.pays||[]).filter(p=>p.t>=from));const exp=DB.expenses.filter(e=>e.t>=from).reduce((a,e)=>a+e.amt,0);
  return {n:inv.length,sales:T.reduce((a,t)=>a+t.sales,0),passOut:T.reduce((a,t)=>a+t.passOut,0),profit:T.reduce((a,t)=>a+t.profit,0),cost:T.reduce((a,t)=>a+t.cost,0),labour:T.reduce((a,t)=>a+t.labour,0),parts:T.reduce((a,t)=>a+t.parts,0),paid:pays.reduce((a,p)=>a+p.amt,0),byM:pays.reduce((o,p)=>(o[p.m]=(o[p.m]||0)+p.amt,o),{}),exp,inv};}
SCREENS.money=m=>{if(!can.money()){go('home');return;}
  const due=dueInvoices().sort((a,b)=>a.inv.t-b.inv.t),dt=due.reduce((a,j)=>a+jobTotals(j).due,0),cd=(+DB.ws.credDays||30)*864e5;
  const td=sumRange(rangeOf('today')),wk=sumRange(rangeOf('week'));
  m.innerHTML=head('Money')+`
  <div class="kpis2"><div class="kpi org"><b>${f3(dt)}</b><span>Due from customers</span></div><div class="kpi ok"><b>${f3(wk.sales)}</b><span>Sales · last 7 days</span></div></div>
  ${sec('Today')}<div class="kpis3"><div class="kpi"><b>${f3(td.sales)}</b><span>Invoiced · ${td.n}</span></div><div class="kpi"><b>${f3(td.paid)}</b><span>Collected</span></div><div class="kpi"><b>${f3(td.exp)}</b><span>Expenses</span></div></div>
  <div class="two"><button class="btn ghost sm" data-go="close">🔒 Daily close</button><button class="btn ghost sm" data-go="exp">🧾 Expenses</button></div>
  <div class="two"><button class="btn ghost sm" data-go="reports">📊 Reports</button><button class="btn ghost sm" data-go="outw">🏪 Other workshops</button></div>
  ${sec('Collect first · '+due.length,`older than ${DB.ws.credDays||30} days in red`)}
  <div class="jb-list">${due.map(j=>{const c=custOf(j),v=vehOf(j),T=jobTotals(j),old=now()-j.inv.t>cd;return `<button class="jb-r it" data-go="inv:${j.id}"><div>${esc(c.name||'')}<small>#${j.inv.no} · ${esc(carName(v))} · ${ago(j.inv.t)}</small></div><b style="${old?'color:var(--bad)':''}">${f3(T.due)}</b></button>`;}).join('')||'<div class="jb-r"><div>Nothing due 👌</div></div>'}</div>`;};
SCREENS.exp=m=>{const f=rangeOf('month');const list=DB.expenses.slice().sort((a,b)=>b.t-a.t);const mon=DB.expenses.filter(e=>e.t>=f);
  const byC={};mon.forEach(e=>byC[e.cat]=(byC[e.cat]||0)+e.amt);
  m.innerHTML=head('Expenses',`<button class="lnk" id="eadd">＋ Expense</button>`)+`
  <div class="kpis2"><div class="kpi red"><b>${f3(mon.reduce((a,e)=>a+e.amt,0))}</b><span>This month</span></div><div class="kpi"><b>${mon.length}</b><span>Entries</span></div></div>
  ${Object.keys(byC).length?sec('This month by type')+`<div class="list">${Object.entries(byC).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<div class="row"><div><b>${esc(c)}</b></div><span class="v">${f3(v)}</span></div>`).join('')}</div>`:''}
  ${sec('All')}<div class="list">${list.map(e=>`<button class="row" data-ee="${e.id}"><div><b>${esc(e.cat)}</b><span>${fmtD(e.t)}${e.note?' · '+esc(e.note):''}${e.monthly?' · monthly':''}</span></div><span class="v">${f3(e.amt)}</span></button>`).join('')||empty('🧾','No expenses yet. Add rent and salaries first.')}</div>`;
  const edit=e=>{const isNew=!e;e=e||{cat:DB.ecats[0],amt:0,t:now()};openSheet(`<h3>${isNew?'New expense':'Edit expense'}</h3><select class="field" id="ec">${DB.ecats.map(c=>`<option ${e.cat===c?'selected':''}>${esc(c)}</option>`).join('')}</select><input class="field" id="ea" inputmode="decimal" placeholder="Amount" value="${e.amt?f3(e.amt):''}"><input class="field" id="en" placeholder="Note" value="${esc(e.note||'')}"><label class="chk"><input type="checkbox" id="em" ${e.monthly?'checked':''}> Every month (rent, salaries…)</label><button class="btn" id="eok">Save</button>${!isNew?'<button class="btn ghost jb-del" id="edel">Delete</button>':''}`,el=>{
    el.querySelector('#eok').onclick=()=>{const a=num($('#ea').value);if(!a){toast('Type the amount');return;}if(isNew){e.id=uid('e');e.by=S.user.name;DB.expenses.push(e);}e.cat=$('#ec').value;e.amt=a;e.note=$('#en').value.trim();e.monthly=$('#em').checked;save();closeSheet();render();};
    const d=el.querySelector('#edel');if(d)d.onclick=()=>{DB.expenses=DB.expenses.filter(x=>x!==e);save();closeSheet();render();};});};
  $('#eadd').onclick=()=>edit();$$('[data-ee]').forEach(b=>b.onclick=()=>edit(DB.expenses.find(x=>x.id===b.dataset.ee)));};
SCREENS.close=m=>{const td=sumRange(rangeOf('today'));const cash=td.byM.Cash||0;const cashExp=DB.expenses.filter(e=>dayKey(e.t)===today()&&e.cash).reduce((a,e)=>a+e.amt,0);
  const last=DB.closes.slice().sort((a,b)=>b.t-a.t)[0];const opening=last?last.counted:(+DB.openingCash||0);const expect=opening+cash-cashExp;const done=DB.closes.find(c=>c.date===today());
  const openJ=openJobs();
  m.innerHTML=head('Daily close · '+fmtDs(now()))+`
  <div class="jb-list"><div class="jb-r"><div>Opening cash<small>${last?'from last close':'set in Settings'}</small></div><b>${f3(opening)}</b></div><div class="jb-r"><div>+ Cash payments today</div><b>${f3(cash)}</b></div>${Object.entries(td.byM).filter(([k])=>k!=='Cash').map(([k,v])=>`<div class="jb-r"><div>${esc(k)}<small>not in the drawer</small></div><b>${f3(v)}</b></div>`).join('')}<div class="jb-r tot"><div>Cash expected in the drawer</div><b>${f3(expect)}</b></div></div>
  ${done?`<div class="card ${Math.abs(done.diff)>0.0005?'note':''}"><div class="h"><b>Closed by ${esc(done.by)} at ${hm(done.t)}</b></div><span class="sub">Counted ${f3(done.counted)} · ${Math.abs(done.diff)<=0.0005?'matches ✓':'difference '+f3(done.diff)}</span></div>`
  :`<label class="field-l">Cash counted in the drawer<input class="field" id="ccnt" inputmode="decimal" placeholder="0.000"></label><button class="btn" id="cok">Close the day</button>`}
  ${openJ.length?sec('Still open · '+openJ.length,'close them or write why')+`<div class="list">${openJ.map(carRow).join('')}</div>`:''}
  ${sec('Past closes')}<div class="list">${DB.closes.slice().sort((a,b)=>b.t-a.t).slice(0,14).map(c=>`<div class="row"><div><b>${fmtD(c.t)}</b><span>${esc(c.by)} · expected ${f3(c.expected)}</span></div><span class="v ${Math.abs(c.diff)>0.0005?'bad':''}">${f3(c.counted)}<small>${Math.abs(c.diff)>0.0005?(c.diff>0?'+':'')+f3(c.diff):'✓'}</small></span></div>`).join('')||empty('🔒','No closes yet.')}</div>`;
  const ok=$('#cok');if(ok)ok.onclick=()=>{const v=$('#ccnt').value.trim();if(v===''){toast('Count the cash first');return;}const c=num(v);DB.closes.push({date:today(),t:now(),by:S.user.name,expected:expect,counted:c,diff:c-expect});save();render();};};
SCREENS.reports=m=>{if(!can.money()){go('home');return;}const k=S.p.k||'month';const R=sumRange(rangeOf(k));
  const svc={},prt={};R.inv.forEach(j=>(j.items||[]).forEach(i=>{const o=i.k==='part'?prt:svc;o[i.d]=o[i.d]||{n:0,a:0};o[i.d].n+=(+i.q||0);o[i.d].a+=(+i.q||0)*(+i.p||0);}));
  const top=o=>Object.entries(o).sort((a,b)=>b[1].a-a[1].a).slice(0,10);
  const days={};DB.jobs.filter(j=>isInvoiced(j)&&j.inv.t>=rangeOf(k)).forEach(j=>{const d=new Date(j.inv.t).toLocaleDateString('en-GB',{weekday:'short',timeZone:'Asia/Muscat'});days[d]=(days[d]||0)+1;});
  m.innerHTML=head('Reports')+`<div class="chips">${[['today','Today'],['week','7 days'],['month','This month'],['year','This year']].map(([x,l])=>`<button data-k="${x}" aria-pressed="${k===x}">${l}</button>`).join('')}</div>
  <div class="kpis3"><div class="kpi ok"><b>${f3(R.sales)}</b><span>Sales · ${R.n} invoices</span></div><div class="kpi"><b>${f3(R.paid)}</b><span>Collected</span></div><div class="kpi red"><b>${f3(R.exp)}</b><span>Expenses</span></div></div>
  ${can.cost()?`<div class="kpis3"><div class="kpi"><b>${f3(R.labour)}</b><span>Labour</span></div><div class="kpi"><b>${f3(R.parts-R.cost)}</b><span>Profit on parts</span></div><div class="kpi ${R.profit-R.exp>=0?'ok':'red'}"><b>${f3(R.profit-R.exp)}</b><span>Net after expenses</span></div></div>`:''}
  ${R.passOut>0.0005?`<p class="hint">${f3(R.passOut)} of work done at other workshops is not counted in sales.</p>`:''}
  ${(()=>{const cm={};R.inv.forEach(j=>(j.items||[]).forEach(i=>{if(+i.comm&&i.by){cm[i.by]=(cm[i.by]||0)+(+i.comm)*(+i.q||1);}}));const e=Object.entries(cm);return can.cost()&&e.length?sec('Commission')+`<div class="list">${e.sort((a,b)=>b[1]-a[1]).map(([n,v])=>`<div class="row"><div><b>${esc(n)}</b></div><span class="v">${f3(v)}</span></div>`).join('')}</div>`:'';})()}
  ${(()=>{const g={};R.inv.forEach(j=>(j.items||[]).forEach(i=>{if(i.rxk==='oil'&&i.k!=='part'){const k=i.rxg||'other';g[k]=(g[k]||0)+1;}}));const n=Object.values(g).reduce((a,b)=>a+b,0);return n?sec('🛢 Oil change choices',n+' oil changes')+`<div class="list">${Object.entries(g).sort((a,b)=>b[1]-a[1]).map(([k,c])=>`<div class="nh-row"><b>${GRADE[k]?GRADE[k][0]:'Other'}</b><span class="r">${Math.round(c/n*100)}%</span><span class="m">${c} times</span><div class="nh-bar"><i style="width:${Math.round(c/n*100)}%;background:var(--ok)"></i></div></div>`).join('')}</div>`:'';})()}
  ${sec('Top services')}<div class="list">${top(svc).map(([n,o])=>`<div class="row"><div><b>${esc(n)}</b><span>${o.n} times</span></div><span class="v">${f3(o.a)}</span></div>`).join('')||empty('📊','No invoices in this period.')}</div>
  ${sec('Top parts')}<div class="list">${top(prt).map(([n,o])=>`<div class="row"><div><b>${esc(n)}</b><span>${+o.n.toFixed(2)} sold</span></div><span class="v">${f3(o.a)}</span></div>`).join('')||''}</div>
  ${Object.keys(days).length?sec('Invoices by day of week')+`<div class="list">${['Sat','Sun','Mon','Tue','Wed','Thu','Fri'].filter(d=>days[d]).map(d=>`<div class="nh-row"><b>${d}</b><span class="r">${days[d]}</span><span class="m"></span><div class="nh-bar"><i style="width:${Math.round(days[d]/Math.max(...Object.values(days))*100)}%;background:var(--red)"></i></div></div>`).join('')}</div>`:''}`;
  $$('[data-k]').forEach(b=>b.onclick=()=>{S.p.k=b.dataset.k;render();});};
/* ---------- SETUP · 100 steps ---------- */
const STEP_LINK={profile:'settings',logo:'settings',vat:'settings',invno:'settings',warranty:'settings',pay:'list:pay',cred:'settings',remind:'settings',remmsg:'settings',backup:'settings',backup2:'settings',manager:'users',worker:'users',owner:'users',svc:'svc',svcadd:'svc',pcat:'list:pcat',oils:'stock',filters:'stock',pprice:'stock',pcost:'stock',reorder:'stock',vendors:'vendors',po:'vendors',porec:'vendors',canned:'canned',insp:'insp',expcat:'list:pcat',exp:'exp',cust5:'cust',job1:'newjob',est2job:'work',inv1:'work',pay3:'money',ret:'work',outside:'work',rem1:'cust',close1:'close',count1:'count'};
SCREENS.setup=m=>{const [d,t]=stepsProgress();const open=S.p.w||STEPS.find(([w,,l])=>l.some(([,a],i)=>!stepDone(w,i,a)))?.[0]||'w1';
  m.innerHTML=head('Setup · 100 steps',`${d}/${t}`)+`<div class="prog"><i style="width:${d/t*100}%"></i></div>
  <p class="hint">Ticks with ✨ tick themselves when the app sees it done. Tap a step with › to go there.</p>
  ${STEPS.map(([w,title,list])=>{const dn=list.filter(([,a],i)=>stepDone(w,i,a)).length;const isO=open===w;return `<button class="wk${isO?' on':''}" data-w="${w}"><b>${title}</b><span>${dn}/${list.length}</span></button>${isO?`<div class="steps">${list.map(([txt,a],i)=>{const done=stepDone(w,i,a);const autoDone=!DB.steps[stepKey(w,i)]&&done;const n=STEPS.slice(0,STEPS.findIndex(x=>x[0]===w)).reduce((s,x)=>s+x[2].length,0)+i+1;return `<div class="stp${done?' done':''}"><button class="cb" data-st="${w}|${i}" ${autoDone?'disabled':''}>${done?'✓':''}</button><div><span class="n">${n}</span>${esc(txt)}${autoDone?' <em>✨</em>':''}</div>${a&&STEP_LINK[a]?`<button class="lnk" data-go="${STEP_LINK[a]}">›</button>`:''}</div>`;}).join('')}</div>`:''}`;}).join('')}`;
  $$('[data-w]').forEach(b=>b.onclick=()=>{S.p.w=S.p.w===b.dataset.w&&open===b.dataset.w?'none':b.dataset.w;render();});
  $$('[data-st]').forEach(b=>b.onclick=()=>{const [w,i]=b.dataset.st.split('|');const k=stepKey(w,+i);DB.steps[k]=!DB.steps[k];if(!DB.steps[k])delete DB.steps[k];save();S.keep=scrollY;render();scrollTo(0,S.keep);});};
/* ---------- SETTINGS ---------- */
SCREENS.settings=m=>{if(!can.settings()){go('more');return;}const w=DB.ws;
  m.innerHTML=head('Settings')+`
  ${sec('Workshop')}
  <div class="logo-up"><label>${w.logo?`<img src="${w.logo}" alt="">`:'<span class="wsmark big">＋</span>'}<input type="file" accept="image/*" id="slogo" hidden><span>${w.logo?'Change logo':'Upload logo'}</span></label>${w.logo?'<button class="lnk" id="slogox">Remove</button>':''}</div>
  <input class="field" id="sname" placeholder="Workshop name" value="${esc(w.name)}"><div class="in2"><input class="field" id="sphone" inputmode="tel" placeholder="Phone" value="${esc(w.phone||'')}"><input class="field" id="saddr" placeholder="Area / city" value="${esc(w.addr||'')}"></div>
  <input class="field" id="scr" placeholder="Commercial registration no. (optional)" value="${esc(w.cr||'')}">
  ${sec('Invoices')}
  <div class="in2"><label class="field-l">Next invoice number<input class="field" id="sinv" inputmode="numeric" value="${w.nextInv}"></label><label class="field-l">Credit days<input class="field" id="scred" inputmode="numeric" value="${w.credDays}"></label></div>
  <label class="chk"><input type="checkbox" id="svat" ${w.vat?'checked':''}> VAT registered (if not, leave off)</label>
  <label class="field-l">Warranty / footer text<textarea class="field" id="swar" rows="2" placeholder="e.g. 3 months warranty on labour. Parts as per maker.">${esc(w.warranty||'')}</textarea></label>
  <button class="mitem" data-go="list:pay"><span class="ic">💳</span><div><b>Payment methods</b><span>${esc(w.pay.join(', '))}</span></div><span class="v">›</span></button>
  ${sec('Reminders')}
  <div class="in2"><label class="field-l">Engine oil · months<input class="field" id="srm" inputmode="numeric" value="${w.remMonths}"></label><label class="field-l">Engine oil · km<input class="field" id="srk" inputmode="numeric" value="${w.remKm}"></label></div>
  <button class="mitem" data-go="msgs"><span class="ic">💬</span><div><b>WhatsApp messages</b><span>Customers, reminders, estimates, invoices, suppliers</span></div><span class="v">›</span></button>
  ${sec('Lists')}
  <button class="mitem" data-go="lists"><span class="ic">🗂</span><div><b>All lists</b><span>Service groups, part categories, units, car makes, expense types, your own lists</span></div><span class="v">›</span></button>
  <label class="field-l">Opening cash in the drawer<input class="field" id="soc" inputmode="decimal" value="${DB.openingCash?f3(DB.openingCash):''}"></label>
  <button class="btn" id="ssave">Save settings</button>
  ${sec('🧪 Test data')}
  <p class="hint">Fake customers, cars, suppliers, parts and jobs to try the app. All have 🧪 in the name. Remove them before real work.</p>
  ${hasDemo()?'<button class="btn ghost sm" id="sdemox">Remove test data</button>':'<button class="btn ghost sm" id="sdemo">🧪 Add test data</button>'}
  ${sec('Backup')}
  <p class="hint">This test app keeps everything on this device only. Make a backup copy often.</p>
  <div class="two"><button class="btn ghost sm" id="sbk">⬇️ Make backup</button><button class="btn ghost sm" id="srs">⬆️ Restore</button></div>
  <button class="btn ghost jb-del" id="swipe">Delete all data on this device</button>`;
  $('#slogo').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,600/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);w.logo=c.toDataURL('image/png');save();render();};im.src=r.result;};r.readAsDataURL(f);};
  const lx=$('#slogox');if(lx)lx.onclick=()=>{w.logo='';save();render();};
  $('#ssave').onclick=()=>{w.name=$('#sname').value.trim()||w.name;w.phone=$('#sphone').value.trim();w.addr=$('#saddr').value.trim();w.cr=$('#scr').value.trim();w.nextInv=Math.max(1,parseInt($('#sinv').value)||w.nextInv);w.invStart=w.invStart||w.nextInv;w.credDays=parseInt($('#scred').value)||30;w.vat=$('#svat').checked;w.vatDecided=true;w.warranty=$('#swar').value.trim();
    w.remMonths=parseInt($('#srm').value)||6;w.remKm=parseInt($('#srk').value)||7000;
    DB.openingCash=num($('#soc').value);save();toast('Saved');render();};
  const sd=$('#sdemo');if(sd)sd.onclick=()=>{loadDemo();};const sdx=$('#sdemox');if(sdx)sdx.onclick=()=>confirmSheet('Remove all test data (everything with 🧪)? Your real data stays.','Remove test data',removeDemo);
  $('#sbk').onclick=async()=>{const txt=JSON.stringify(DB);DB.backups=(DB.backups||0)+1;save();const name='workshop-backup-'+today()+'.json';
    try{if(navigator.canShare&&navigator.canShare({files:[new File([txt],name)]})){await navigator.share({files:[new File([txt],name,{type:'application/json'})],title:name});return;}}catch(e){}
    try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'application/json'}));a.download=name;a.click();}catch(e){}
    if(navigator.clipboard)navigator.clipboard.writeText(txt).then(()=>toast('Backup copied. Paste it in a note or WhatsApp to yourself.')).catch(()=>{});};
  $('#srs').onclick=()=>openSheet(`<h3>Restore a backup</h3><p class="hint">This replaces everything on this device.</p><input type="file" accept="application/json,.json" id="rf" class="field"><textarea class="field" id="rt" rows="5" placeholder="…or paste the backup text here"></textarea><button class="btn" id="rok">Restore</button>`,el=>el.querySelector('#rok').onclick=async()=>{let t=$('#rt').value.trim();const f=$('#rf').files[0];if(f)t=await f.text();try{const d=JSON.parse(t);if(!d.ws)throw 0;DB=Object.assign(blankDB(),d);save();closeSheet();S.user=null;render();toast('Restored');}catch(e){toast('That is not a backup file');}});
  $('#swipe').onclick=()=>confirmSheet('Delete ALL data on this device? This cannot be undone.','Delete everything',()=>{localStorage.removeItem(KEY);DB=blankDB();S.user=null;OB.step=0;render();});};
/* ---------- USERS ---------- */
SCREENS.users=m=>{if(!can.settings()){go('more');return;}
  const nCust=u=>u.role!=='owner'&&u.perm?Object.keys(u.perm).length:0;
  m.innerHTML=head('Users',`<button class="lnk" id="uadd">＋ Add</button>`)+`
  <div class="card note"><b>Who can do what</b><span class="sub"><b>Owner</b>: everything.<br><b>Manager</b> and <b>Worker</b> start with a set of permissions. Tap a person to turn each one on or off.</span></div>
  <div class="list">${DB.users.map(u=>`<button class="row" data-ue="${u.id}"><div style="display:flex;gap:12px;align-items:center"><span class="av" style="background:${u.color}">${initials(u.name)}</span><div><b>${esc(u.name)}</b><span>${ROLE[u.role]}${nCust(u)?' · custom permissions':''}</span></div></div><span class="v">Edit</span></button>`).join('')}</div>`;
  const edit=u=>{const isNew=!u;u=u||{role:'worker'};let role=u.role;let pm=Object.assign({},u.perm||{});
    openSheet(`<h3>${isNew?'New user':'Edit '+esc(u.name)}</h3><input class="field" id="un" placeholder="Name" value="${esc(u.name||'')}">
     <div class="chips" id="uro"></div>
     <input class="field" id="up" inputmode="numeric" maxlength="4" placeholder="${isNew?'4-number PIN':'New PIN (leave empty to keep)'}">
     <div class="field-l" style="display:flex;justify-content:space-between;align-items:center">What ${isNew?'they':esc(u.name)} can see and do <button class="lnk" id="urst" style="min-height:0;padding:0">Reset to ${'role'}</button></div>
     <div class="list" id="upm"></div>
     <button class="btn" id="uok">Save</button>${!isNew&&u.id!==S.user.id?'<button class="btn ghost jb-del" id="udel">Remove user</button>':''}`,el=>{
     const draw=()=>{el.querySelector('#uro').innerHTML=['owner','manager','worker'].map(r=>`<button data-r="${r}" aria-pressed="${role===r}">${ROLE[r]}</button>`).join('');
       el.querySelector('#urst').hidden=role==='owner'||!Object.keys(pm).length;
       el.querySelector('#upm').innerHTML=role==='owner'?'<p class="hint">The owner can see and do everything.</p>':PERMS.map(([k,t,d])=>{const on=k in pm?!!pm[k]:roleDef(role,k);return `<label class="lrow tgl2"><span class="lname"><div><b>${t}${k in pm?' <span class="tg tgr">changed</span>':''}</b><span>${d}</span></div></span><input type="checkbox" data-pk="${k}" ${on?'checked':''}></label>`;}).join('');
       el.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{role=b.dataset.r;pm={};draw();});
       el.querySelectorAll('[data-pk]').forEach(b=>b.onchange=()=>{const k=b.dataset.pk;if(b.checked===roleDef(role,k))delete pm[k];else pm[k]=b.checked;draw();});};
     draw();el.querySelector('#urst').onclick=()=>{pm={};draw();};
     el.querySelector('#uok').onclick=async()=>{const n=$('#un').value.trim();const pin=$('#up').value.trim();if(!n){toast('Type a name');return;}if(isNew&&!/^\d{4}$/.test(pin)){toast('PIN must be 4 numbers');return;}if(pin&&!/^\d{4}$/.test(pin)){toast('PIN must be 4 numbers');return;}
       if(!isNew&&u.role==='owner'&&role!=='owner'&&DB.users.filter(x=>x.role==='owner').length===1){toast('Keep at least one owner');return;}
       if(isNew){u.id=uid('u');u.color=COLORS[DB.users.length%COLORS.length];DB.users.push(u);}u.name=n;u.role=role;u.perm=role==='owner'?{}:pm;if(pin)u.pin=await hashPin(pin);save();closeSheet();render();};
     const d=el.querySelector('#udel');if(d)d.onclick=()=>confirmSheet('Remove '+esc(u.name)+'?','Remove',()=>{DB.users=DB.users.filter(x=>x!==u);save();render();});});};
  $('#uadd').onclick=()=>edit();$$('[data-ue]').forEach(b=>b.onclick=()=>edit(DB.users.find(x=>x.id===b.dataset.ue)));};
/* ---------- MORE ---------- */
SCREENS.more=m=>{const [d,t]=stepsProgress();const it=(r,ic,t2,s,show=true)=>show&&routeOk(r)&&!DB.hideMenu[r]?`<button class="mitem" data-go="${r}"><span class="ic">${ic}</span><div><b>${t2}</b><span>${s}</span></div><span class="v">›</span></button>`:'';
  const ml=DB.mlists.filter(L=>L.inMenu!==false);
  m.innerHTML=head('More')+`<div class="list">
  ${it('news','🎉','What\'s new · how to use',newsUnseen().length?'<b style="color:var(--red2)">'+newsUnseen().length+' new</b> · tap to see':'Tours of every new thing')}${it('setup','✅','Setup · 100 steps',`${d} of ${t} done`)}
  ${it('svc','🛠','Services',DB.services.length+' services · '+DB.scats.length+' groups')}
  ${it('stock','🛢','Stock',DB.parts.length+' parts')}
  ${it('vendors','🚚','Suppliers & orders',DB.vendors.length+' suppliers')}
  ${it('canned','📦','Canned jobs',DB.canned.length+' sets')}
  ${it('insp','📋','Inspection checklists',DB.insp.length+' checklists')}
  ${it('count','🔢','Daily count','5 items a day')}
  ${it('money','💰','Money','Due, today, collect',can.money())}
  ${it('exp','🧾','Expenses','Rent, salaries, supplies',can.money())}
  ${it('close','🔒','Daily close','Match the cash drawer',can.money())}
  ${it('reports','📊','Reports','Sales, profit, top items',can.money())}
  </div>
  ${ml.length?sec('Your lists')+`<div class="list">${ml.map(L=>it('list:'+L.id,L.ic||'📝',esc(L.name),L.items.length+' items')).join('')}</div>`:''}
  ${can.settings()?sec('Customize')+`<div class="list">${it('lists','🗂','Lists','Groups, categories, units, payment methods, your own lists')}${it('msgs','💬','WhatsApp messages','Customers, reminders, suppliers')}${it('users','👥','Users','Who sees what')}${it('settings','⚙️','Settings','Workshop, invoices, backup')}</div>`:''}
  <button class="btn ghost" id="lo">Log out (${esc(S.user.name)})</button><p class="hint" id="verh" style="text-align:center">Test version ${esc(window.WS_VN||"")} · data stays on this device · updates by itself</p>`;
  $('#lo').onclick=()=>{S.user=null;render();};};
