function msgTpl(k){const m=DB.ws.msgs||{};if(m[k]!=null&&m[k]!=='')return m[k];if(k==='remind'&&DB.ws.remMsg)return DB.ws.remMsg;return (MSGS.find(x=>x[0]===k)||[])[5]||'';}
